-- Soal tambahan modul 9 (kuis Parang Kusumo dari layar kuis app) dan soal baru modul 18.
WITH v(mod, question, a, b, c, d, correct, explanation) AS (VALUES
(9,'Motif Batik Parang Kusumo secara filosofis melambangkan ... yang tidak pernah padam dalam menghadapi ujian hidup.','semangat perjuangan dan keteguhan hati','ketenangan danau keraton yang syahdu','keagungan senjata keris pusaka Mataram','kesuburan tanah dan hasil bumi Nusantara','A','Kata ''Kusumo'' bermakna bunga ksatria. Bentuk lereng miring menyerupai deburan ombak karang laut selatan menggambarkan gelombang tekad pantang menyerah, keteguhan hati, serta budi pekerti luhur ksatria Jawa.'),
(9,'Ciri khas kemiringan garis lereng pada motif Parang Kusumo adalah sebesar ... derajat.','30','45','60','90','B','Kemiringan lereng 45 derajat melambangkan keteguhan arah dan konsistensi jalan hidup seorang ksatria.'),
(9,'Motif Parang Kusumo diciptakan oleh raja Keraton Mataram pada masa pemerintahan ....','Sultan Agung Hanyakrakusuma','Panembahan Senopati','Sri Sultan Hamengkubuwono I','Pakubuwana IV','B','Motif Parang Kusumo digubah oleh Panembahan Senopati saat bertapa di Pantai Parangtritis dan terinspirasi oleh deburan ombak karang.'),
(9,'Ornamen belah ketupat yang mengisi sela-sela lereng motif Parang dikenal dengan nama ....','Cecek','Kaut','Mlinjon','Isen','C','Mlinjon melambangkan senjata perisai atau benteng perlindungan moral dalam menghadapi godaan hidup.'),
(18,'Siapakah yang menciptakan motif Truntum?','Panembahan Senopati','Kanjeng Ratu Kencana, permaisuri Pakubuwono III','Sultan Agung','Pangeran Diponegoro','B','Truntum diciptakan Kanjeng Ratu Kencana saat merenung menatap bintang sambil mencanting untuk menumbuhkan kembali cinta kasih sang Raja.'),
(18,'Kata Truntum berasal dari kata taruntum yang berarti...','Bersemi atau tumbuh kembali','Awan pembawa hujan','Lereng karang','Empat penjuru','A','Truntum bermakna bersemi atau tumbuh kembali, lambang cinta kasih yang tulus tanpa pamrih.'),
(18,'Pada upacara pernikahan adat Jawa, motif Truntum wajib dikenakan oleh...','Pengantin laki-laki','Orang tua pengantin','Para tamu undangan','Juru rias','B','Orang tua pengantin mengenakan Truntum sebagai doa agar cinta kedua mempelai selalu bersemi dan mampu menjadi panutan hidup.'),
(18,'Bagaimana latar warna pakem Truntum?','Putih bersih tanpa warna lain','Hitam atau cokelat pekat tanpa corak latar tambahan','Biru muda bergradasi','Merah menyala','B','Latar gelap pekat menyerupai langit malam, tempat kuntum bintang melati tersebar rapi.')
)
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_option, explanation)
SELECT m.id, v.question, v.a, v.b, v.c, v.d, v.correct, v.explanation
FROM v JOIN modules m ON m.order_no = v.mod;

-- Materi lengkap 3 pilar modul lainnya (mengikuti struktur acuan Parang Kusumo)
WITH v(mod, pillar, order_no, title, body, badge) AS (VALUES
(1,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Betawi memancarkan jiwa keterbukaan, keramahan, dan keberanian masyarakat ibu kota dalam mengarungi dinamika zaman. Warna-warnanya yang cerah dan menyala mencerminkan semangat egaliter, kegembiraan hidup, serta ketulusan budi pekerti warga Betawi yang menjunjung tinggi persaudaraan dan kejujuran tanpa kepalsuan.',NULL),
(1,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berkembang pesat sejak abad ke-19 di sentra-sentra pembatikan Batavia seperti Palmerah, Karet Tengsin, Tanah Abang, dan Kebayoran Lama. Dipengaruhi oleh akulturasi multikultural yang kaya antara kebudayaan Sunda, Melayu, Tionghoa, Arab, dan Eropa yang bermukim di pesisir barat Pulau Jawa.',NULL),
(1,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Setiap motif merekam denyut kehidupan warga Jakarta. Ikon Ondel-ondel melambangkan pelindung warga dari mara bahaya dan penolak bala, Monas menyimbolkan tekad perjuangan dan cita-cita luhur bangsa, Kembang Kelapa melambangkan kemakmuran dan keberkahan rezeki, serta Sungai Ciliwung yang mengingatkan pentingnya menjaga sumber air kehidupan.',NULL),
(1,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Batik Betawi lazim dikenakan pada perayaan hari besar kebudayaan seperti Lebaran Betawi, upacara pernikahan adat Betawi (pakaian Abang None), upacara Palang Pintu, serta festival seni dan busana resmi daerah DKI Jakarta.',NULL),
(1,'karakteristik',1,'Anatomi Visual','Struktur visual Batik Betawi menampilkan komposisi figuratif yang ekspresif, spontan, dan sarat dengan ikon-ikon khas lanskap budaya Jakarta.',NULL),
(1,'karakteristik',2,'Ikon Khas Ondel-Ondel & Monas','Figur boneka raksasa adat dan tugu kebanggaan nasional digubah secara artistik.','Struktur Utama • Ikonik'),
(1,'karakteristik',3,'Isen Kembang Kelapa & Cecek','Hiasan rumbai bunga kelapa dan taburan titik canting menghiasi latar kain mori.','Isen Halus Betawi'),
(1,'karakteristik',4,'Warna Berani & Cerah','Didominasi warna merah terang, kuning kunyit, hijau pupus, dan biru pesisiran.','Warna Pesisiran Cerah'),
(1,'karakteristik',5,'Sudut Pandang Dinamis','Ragam hias ditata bebas dan mengalir tanpa terikat pola simetri kaku keraton.',NULL),
(1,'karakteristik',6,'Kontur Garis Tegas','Garis lilin malam ditarik dengan ketebalan sedang menghasilkan batas visual yang sangat jelas.',NULL),
(1,'karakteristik',7,'Variasi Motif Flora-Fauna','Kombinasi burung hong, kembang sepatu, dan pucuk rebung menghiasi tepi kain (tumpal).',NULL),
(1,'karakteristik',8,'Dimensi Figuratif Menonjol','Skala ornamen ikonik dibuat proporsional dan mudah dikenali dari kejauhan.',NULL),
(2,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Bokor Kencono merepresentasikan kesiapan batin manusia untuk menjadi bejana suci penampung rahmat Tuhan. Sebagaimana cawan emas yang berkilau menampung tirta amerta, motif ini mengajarkan bahwa kemuliaan derajat seseorang berakar dari kebersihan hati, kelapangan jiwa menampung ilmu kebajikan, serta kedermawanan dalam membagikan berkah kepada sesama manusia.',NULL),
(2,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan di lingkungan Keraton Kasunanan Surakarta Hadiningrat oleh para abdi dalem perajin batik istana. Terilhami oleh piranti pusaka bokor kencana yang senantiasa hadir dalam upacara-upacara sakral penobatan raja dan pisowanan agung para bangsawan keraton.',NULL),
(2,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Kata ''Bokor'' bermakna wadah bejana logam berukir indah, sedangkan ''Kencono'' bermakna emas murni bernilai luhur. Filosofinya menegaskan bahwa manusia yang berbudi pekerti emas akan senantiasa dilimpahi kemakmuran, wibawa kepemimpinan yang agung, serta dihormati karena keteguhan moralitasnya.',NULL),
(2,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara tradisional dikenakan oleh para bangsawan dan kerabat keraton Surakarta dalam upacara adat resmi, pertemuan penting pisowanan dalem, serta upacara perkawinan adat sebagai doa kemakmuran bagi rumah tangga baru.',NULL),
(2,'karakteristik',1,'Anatomi Visual','Mengedepankan komposisi pola geometris melingkar berulang yang elegan dengan ornamen bokor bersulur emas di atas latar sogan.',NULL),
(2,'karakteristik',2,'Bentuk Bejana Bokor Geometris','Pola wadah bundar berlekuk teratur membentuk irama bidang yang simetris.','Struktur Utama • Bejana Sakral'),
(2,'karakteristik',3,'Isen Sawut Lung-Lungan Emas','Garis-garis lembut dedaunan sulur meliuk mengisi ruang dalam wadah bokor.','Isen Canting Halus'),
(2,'karakteristik',4,'Pewarna Alami Sogan Klasik','Paduan warna soga jambal cokelat kemerahan, kayu tegeran kuning, dan wedel nila.','Warna Tradisi Keraton'),
(2,'karakteristik',5,'Susunan Kisi Teratur','Bidang motif tersusun dalam keteraturan pola kisi melingkar yang seimbang.',NULL),
(2,'karakteristik',6,'Cecek Pitu pada Mahkota Wadah','Bintik-bintik canting tujuh titik melambangkan pitulungan atau pertolongan ilahi.',NULL),
(2,'karakteristik',7,'Garis Kontur Halus Berwibawa','Tarikan malam canting nomor satu menghasilkan garis pola yang amat presisi.',NULL),
(2,'karakteristik',8,'Pola Berulang Tanpa Awal Akhir','Repetisi lingkaran melambangkan siklus kehidupan manusia yang berkesinambungan.',NULL),
(3,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Buketan merupakan simfoni keindahan lintas benua yang merayakan keharmonisan cinta kasih, keanggunan alam hayati, dan sukacita kehidupan. Rangkaian bunga yang mekar serasi melambangkan ketenteraman jiwa, kelembutan tutur kata, serta kemampuan merangkul perbedaan budaya menjadi satu kesatuan estetika yang mempesona.',NULL),
(3,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Lahir di pesisir Kota Pekalongan pada akhir abad ke-19 hingga awal abad ke-20. Dipelopori oleh perancang busana Indo-Eropa terkemuka seperti Eliza van Zuylen, Carolina von Franquemont, dan Catharina de Beer yang memadukan selera flora Eropa dengan ketelitian seni batik bumiputera.',NULL),
(3,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''boeket'' (bahasa Belanda yang bermakna karangan atau rangkaian bunga). Menyiratkan doa agar kehidupan manusia senantiasa semerbak harum oleh karya kebajikan, dikelilingi oleh sahabat setia, serta dilimpahi kebahagiaan laksana taman bunga musim semi.',NULL),
(3,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Semula dikenakan oleh kaum wanita keturunan Indo-Eropa dan peranakan bangsawan pesisir dalam perjamuan dansa dan pesta pernikahan. Kini digemari luas sebagai kain sarung dan busana kebaya anggun dalam berbagai perhelatan resmi modern.',NULL),
(3,'karakteristik',1,'Anatomi Visual','Menampilkan komposisi asimetris naturalis berupa rumpun karangan bunga berukuran besar yang dikerumuni satwa pesisir lincah.',NULL),
(3,'karakteristik',2,'Rangkaian Buket Bunga Naturalis','Gubahan bunga mawar, tulip, dahlia, dan aster ditata dinamis merumpun.','Struktur Utama • Karangan Bunga'),
(3,'karakteristik',3,'Fauna Kupu-Kupu & Burung Kolibri','Serangga dan burung kecil penghisap madu melayang di sekitar pucuk bunga.','Isen-Isen Hidup'),
(3,'karakteristik',4,'Pewarnaan Pastel Pesisiran Halus','Gradasi warna merah muda, toska, ungu lembayung, dan kuning mentega.','Pewarna Pastel Cerah'),
(3,'karakteristik',5,'Tata Letak Bebas Mengalir','Tata letak bebas tanpa sekat garis geometris memberikan kesan ruang yang lapang.',NULL),
(3,'karakteristik',6,'Teknik Canting Coletan Kuas','Pewarnaan menggunakan kuas bambu kecil menghasilkan detail rona gradasi kelopak.',NULL),
(3,'karakteristik',7,'Garis Kelopak Halus & Lentur','Lekukan garis canting malam sangat tipis mengabadikan kelembutan mahkota bunga.',NULL),
(3,'karakteristik',8,'Kepala Sarung Bertumpal Bunga','Ujung sarung dihiasi susunan bunga menjalar yang berpadu dengan papan tumpal.',NULL),
(4,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Dayak memancarkan kedalaman spiritual masyarakat adat pedalaman hutan tropis Kalimantan yang hidup menyatu dengan nafas alam semesta. Goresan motifnya sarat dengan energi purba yang menjaga keseimbangan antara jagad raya (alam atas), bumi manusia (alam tengah), dan kedalaman air/tanah (alam bawah). Keberanian garisnya mencerminkan keteguhan ksatria penjaga rimba leluhur.',NULL),
(4,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berakar dari kebudayaan luhur rumpun suku Dayak (Kenyah, Ngaju, Iban, Bahau, dan Kayan) di pulau Kalimantan. Ragam motifnya bertransformasi dari media ukiran kayu ulin rumah betang, anyaman tikar purun, manik-manik sakral, tameng perisai mandau, serta rajah tubuh (tedak/tato tradisi) menuju media kain mori batik nusantara.',NULL),
(4,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Mengangkat pohon hayat Batang Garing sebagai lambang poros penciptaan dan kesuburan hidup. Burung Enggang Gading (Tingang) melambangkan keagungan pemimpin yang setia melindungi rakyatnya, sementara ornamen sulur melingkar (kalawit) melambangkan kebersamaan erat yang tak dapat dipisahkan oleh tipu daya dunia.',NULL),
(4,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Dikenakan pada upacara sakral adat seperti pesta panen Gawai Dayak, upacara penyambutan tamu kehormatan di Rumah Betang, tarian perang mandau, serta busana kebanggaan festival budaya Dayak di seluruh penjuru Kalimantan.',NULL),
(4,'karakteristik',1,'Anatomi Visual','Komposisi ornamen melengkung dinamis berkarakter mistis yang terinspirasi dari pola ukiran kayu ulin dan tameng perang Dayak.',NULL),
(4,'karakteristik',2,'Pohon Hayat & Burung Enggang','Figur burung berparuh gading besar bertengger di dahan pohon kehidupan.','Struktur Utama • Sakral'),
(4,'karakteristik',3,'Sulur Kalawit & Pilin Berganda','Garis lengkung saling kait berpusar melambangkan pertalian tali persaudaraan.','Isen Ukir Khas'),
(4,'karakteristik',4,'Warna Kontras Magis Pedalaman','Kombinasi warna kuning kunyit emas, merah darah, hitam arang, dan putih.','Warna Adat Dayak'),
(4,'karakteristik',5,'Simetri Bidang Tameng Belanga','Penataan motif terpusat mengadaptasi pola perisai perang pelindung raga.',NULL),
(4,'karakteristik',6,'Canting Garis Tebal Bertenaga','Goresan lilin malam ditarik dengan mantap menyerupai sayatan pahat kayu.',NULL),
(4,'karakteristik',7,'Hiasan Manik-Manik & Taring','Ornamen pengisi terinspirasi dari untaian kalung manik batu dan gigi satwa.',NULL),
(4,'karakteristik',8,'Irama Sirkular Dinamis','Ragam hias mengalir tanpa sudut tajam melambangkan pusaran arus sungai rimba.',NULL),
(5,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Jlamprang merupakan monumen visual perjumpaan peradaban maritim yang mencerminkan harmoni kosmos, ketertiban semesta, dan hubungan transendental antara manusia dan Sang Maha Kuasa. Pola geometrisnya yang simetris tanpa figur makhluk hidup mengajarkan kejernihan akal budi, konsistensi moral, serta pengendalian diri dalam tatanan hidup bermasyarakat.',NULL),
(5,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berkembang di Kampung Krapyak, Kota Pekalongan sejak abad ke-18. Berakar dari hubungan dagang rempah masa lampau dengan para saudagar Gujarat (India) yang membawa kain sutra tenun ganda Patola yang bernilai sangat tinggi. Oleh para pembatik Muslim pesisir Pekalongan, motif sakral patola tersebut digubah ulang ke dalam media batik perintang malam.',NULL),
(5,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari gubahan pola bintang bersegi delapan (mandala) dan roda cakra yang berputar seimbang. Melambangkan empat penjuru mata angin utama beserta poros spiritualnya, mengingatkan manusia bahwa hidup harus seimbang antara urusan duniawi dan pengabdian spiritual kepada Sang Pencipta.',NULL),
(5,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara kultural sangat dihormati di kalangan masyarakat pesisir Pekalongan, terutama dalam ritual upacara sedekah laut Nyadran di Pantai Krapyak, perayaan Syawalan (tradisi Lopisan raksasa), dan busana kehormatan perhelatan adat pesisiran.',NULL),
(5,'karakteristik',1,'Anatomi Visual','Komposisi geometris murni berpola simetri radial menyerupai bintang delapan arah dan ornamen lingkaran mandala berulang.',NULL),
(5,'karakteristik',2,'Bintang Mandala Segi Delapan','Pola roset geometris tersusun presisi di tengah bidang kotak kisi bujur sangkar.','Struktur Utama • Geometris'),
(5,'karakteristik',3,'Cecek Cakra & Garis Silang','Taburan titik canting melingkar menyerupai roda pedati di sela-sela bidang bintang.','Isen Geometris Halus'),
(5,'karakteristik',4,'Palet Warna Pesisiran Hangat','Kombinasi warna merah mengkudu, hijau pupus, kuning tua, dan biru nila gelap.','Warna Tradisi Pesisir'),
(5,'karakteristik',5,'Simetri Radial Sempurna','Setiap kuadran motif memiliki proporsi yang sama persis saat dilipat horizontal maupun vertikal.',NULL),
(5,'karakteristik',6,'Canting Garis Lurus Presisi','Tarikan malam membutuhkan kemahiran tinggi untuk menjaga keteraturan garis kisi mori.',NULL),
(5,'karakteristik',7,'Variasi Isen Sawut Bintang','Larik-larik sawut halus menghiasi kelopak bintang memberi kesan kedalaman dimensi.',NULL),
(5,'karakteristik',8,'Struktur Kisi Papan Catur','Bidang motif dibagi rata dalam kotak-kotak bujur sangkar menyerupai jalinan tenun ganda.',NULL),
(7,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Liong memancarkan kekuatan kosmis, keberanian tak gentar, serta limpahan kemakmuran hidup hasil akulturasi harmonis antara peradaban Tionghoa dan kearifan bumiputera Nusantara. Figur naga agung yang meliuk di angkasa mengajarkan manusia untuk senantiasa mengarahkan cita-cita setinggi langit dengan jiwa yang kuat melindungi orang-orang yang lemah.',NULL),
(7,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berkembang pesat di kota-kota pelabuhan pesisir utara Jawa seperti Lasem (Rembang), Semarang, Juwana, Pekalongan, dan Cirebon sejak abad ke-15. Terjalin erat seiring jejak persahabatan ekspedisi Laksamana Cheng Ho dan permukiman saudagar Tionghoa yang membaur turun-temurun bersama para pembatik Jawa.',NULL),
(7,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Kata ''Liong'' bermakna naga agung dalam mitologi Tionghoa. Naga adalah makhluk suci penguasa air, awan, dan hujan yang melambangkan kekuasaan yang adil, kemuliaan derajat, keberuntungan tak terputus (hoki), dan penolak bala dari roh jahat. Sering dipadukan dengan burung Phoenix (Hong) sebagai lambang keharmonisan Yang dan Yin.',NULL),
(7,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara tradisional dikenakan dalam perayaan Tahun Baru Imlek, upacara Cap Go Meh, pesta pernikahan peranakan Tionghoa, serta busana kehormatan para saudagar dan bangsawan pesisiran.',NULL),
(7,'karakteristik',1,'Anatomi Visual','Komposisi figuratif dinamis bergelombang menampilkan liukan tubuh naga bersisik tajam yang melintasi awan dan samudera.',NULL),
(7,'karakteristik',2,'Figur Naga Liong Berkumis & Bersisik','Kepala naga bertanduk rusa, berjanggut, dengan cakar tajam mencengkeram mustika.','Struktur Utama • Naga Mistik'),
(7,'karakteristik',3,'Isen Sisik Naga & Cecek Sawut','Sisik tubuh naga digarap sangat detail dengan titik canting cecek berundak.','Isen Sisik Halus'),
(7,'karakteristik',4,'Merah Getih Pitik & Biru Tarum','Warna merah darah ayam khas Lasem yang legendaris berpadu biru tarum pekat.','Warna Akulturasi Lasem'),
(7,'karakteristik',5,'Garis Dinamis Meliuk Megah','Tubuh naga membentang meliuk di sepanjang kain memberikan ilusi gerak hidup.',NULL),
(7,'karakteristik',6,'Ornamen Pendamping Burung Hong','Burung phoenix berbulu ekor menjuntai melengkapi harmoni kekuatan dan keanggunan.',NULL),
(7,'karakteristik',7,'Awan Kemegahan & Air Samudera','Latar ombak air dan awan spiral mengiringi pergerakan sang naga kosmis.',NULL),
(7,'karakteristik',8,'Kontur Malam Tajam Tembus Balik','Goresan lilin malam menembus sempurna ke sisi belakang mori sutra halus.',NULL),
(10,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Sekar Jagad merupakan puncak perayaan keberagaman visual yang merangkum keelokan bunga-bunga semesta ke dalam sehelai bentangan mori. Garis-garis pembatasnya yang berkelok laksana pulau-pulau di peta bumi mengajarkan nilai luhur toleransi, persatuan dalam perbedaan, serta kearifan memandang bahwa setiap insan memiliki keunikan pesona yang saling melengkapi dalam harmoni jagad raya.',NULL),
(10,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berkembang di lingkungan Keraton Kasunanan Surakarta dan Kasultanan Yogyakarta sejak abad ke-18. Diciptakan oleh para maestro pembatik keraton sebagai mahakarya agung yang memadukan aneka macam motif batik klasik tertua tanah Jawa ke dalam satu kesatuan komposisi yang memukau.',NULL),
(10,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Sekar'' (bunga yang mekar semerbak) dan ''Jagad'' (alam semesta/dunia). Secara harfiah bermakna ''Kumpulan Bunga-Bunga Dunia''. Mengandung doa agar pemakainya memancarkan pesona daya tarik kebajikan, disenangi banyak orang, serta mampu menghadirkan kedamaian di mana pun ia berada.',NULL),
(10,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Dikenakan dalam upacara perhelatan agung seperti busana orang tua dan kerabat dalam upacara pernikahan adat Jawa, upacara wisuda kebesaran, serta resepsi kenegaraan resmi sebagai perlambang kelapangan hati dan wibawa budi luhur.',NULL),
(10,'karakteristik',1,'Anatomi Visual','Komposisi mozaik asimetris harmonis yang membagi kain ke dalam bidang-bidang pulau ornamen dengan isen yang berbeda-beda.',NULL),
(10,'karakteristik',2,'Bidang Pulau Mozaik Berkelok','Garis kontur meliuk membagi kain menyerupai pulau-pulau pada peta atlas dunia.','Struktur Utama • Peta Mozaik'),
(10,'karakteristik',3,'Isen-Isen Klasik Campuran','Setiap bidang pulau diisi motif berbeda: kawung, parang kecil, truntum, dan cecek sawut.','Isen Canting Rumit'),
(10,'karakteristik',4,'Harmonisasi Sogan Keraton','Paduan warna soga cokelat matang, hitam malam, dan kontur putih pembatas mori.','Warna Tradisi Luhur'),
(10,'karakteristik',5,'Garis Batas Putih Meliuk (Gegaran)','Garis kontur tipis putih mori memisahkan tiap pulau secara tegas dan anggun.',NULL),
(10,'karakteristik',6,'Kerapatan Canting Ekstrem','Hampir tidak ada bidang kain yang dibiarkan kosong tanpa goresan canting isen halus.',NULL),
(10,'karakteristik',7,'Keseimbangan Visual Asimetris','Meski motif di setiap pulau berbeda, bobot visual keseluruhan kain tetap seimbang.',NULL),
(10,'karakteristik',8,'Kaya Filosofi Multi-Dimensi','Menggabungkan pesan moral dari puluhan motif klasik ke dalam satu helai kain jarik.',NULL),
(11,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Sidoluhur memancarkan kemuliaan batin dan keagungan budi pekerti manusia yang senantiasa menjaga kesucian akhlak di hadapan Sang Maha Pencipta. Motif ini mengajarkan bahwa hakikat derajat luhur bukanlah tahta kekuasaan atau tumpukan harta semata, melainkan kemampuan pribadi mengendalikan hawa nafsu, bertutur kata santun, berjiwa ksatria, dan menebar manfaat bagi masyarakat luas.',NULL),
(11,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan dan dilestarikan secara turun-temurun di lingkungan Keraton Surakarta Hadiningrat dan Kesultanan Yogyakarta sejak era Mataram Islam. Merupakan bagian agung dari empat serangkai motif keluarga ''Sido'' (Sidomukti, Sidoluhur, Sidomulyo, dan Sidoasih).',NULL),
(11,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Sido'' (menjadi, terlaksana, atau terus berkesinambungan) dan ''Luhur'' (mulia, berbudi pekerti tinggi, terhormat, dan diberkahi). Mengandung doa restu yang khusyuk agar pemakainya menjadi pribadi yang luhur budinya, dihormati karena integritas moralnya, serta senantiasa dilindungi dalam kebaikan.',NULL),
(11,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara sakral dikenakan oleh mempelai pengantin pada saat upacara panggih (temu pengantin) dalam adat Jawa, serta dikenakan oleh para bangsawan dan sesepuh keraton dalam upacara tingkeban (mitoni) dan pisowanan agung.',NULL),
(11,'karakteristik',1,'Anatomi Visual','Komposisi geometris belah ketupat (wajik) yang teratur, memuat ornamen sakral kosmik di setiap bidang kotaknya.',NULL),
(11,'karakteristik',2,'Ornamen Meru & Pohon Hayat','Pola gunung suci bertingkat tiga dan pohon kehidupan tersusun megah di dalam wajik.','Struktur Utama • Sakral Meru'),
(11,'karakteristik',3,'Sayap Garuda (Lar) & Kupu-Kupu','Ornamen sayap keteguhan iman dan kupu-kupu keindahan metamorfosis budi.','Isen Sakral Luhur'),
(11,'karakteristik',4,'Pewarnaan Sogan Medhok Keraton','Dominasi cokelat soga tua jambal kemerahan berpadu dasar putih gading mori prima.','Warna Klasik Sogan'),
(11,'karakteristik',5,'Pola Kisi Geometris Wajik','Susunan belah ketupat simetris membingkai tiap ornamen dalam tatanan tertib.',NULL),
(11,'karakteristik',6,'Canting Cecek Sawut Halus','Larik-larik sawut melengkung menghiasi lereng meru dengan presisi tinggi.',NULL),
(11,'karakteristik',7,'Isen Ukel Latar Merata','Latar bidang kain diisi pola ukel lilin malam yang rapat dan teratur.',NULL),
(11,'karakteristik',8,'Dimensi Ornamen Proporsional','Skala meru dan lar garuda seimbang memberikan aura wibawa yang tenang.',NULL),
(12,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Sidomukti merepresentasikan puncak harapan akan terwujudnya kebahagiaan sejati, kemakmuran rezeki yang melimpah, dan ketenteraman batin yang langgeng. Keindahan ornamennya mengajarkan bahwa kemakmuran (''mukti'') sejati bukan semata melimpahnya materi keduniawian, melainkan kecukupan jiwa yang senantiasa bersyukur, rukun dalam berkeluarga, dan mampu mengayomi sesama.',NULL),
(12,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan dan dibakukan di lingkungan Keraton Kasunanan Surakarta Hadiningrat dan Kesultanan Yogyakarta sejak era Mataram Islam. Merupakan busana kebesaran utama pengantin adat Jawa yang paling tersohor dan wajib hadir dalam prosesi pernikahan agung.',NULL),
(12,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Sido'' (menjadi, terlaksana, atau terus-menerus) dan ''Mukti'' (makmur, sejahtera, mulia, berkecukupan rezeki, dan bahagia lahir batin). Mengandung untaian doa restu suci dari orang tua agar kedua mempelai yang mengikat janji suci senantiasa dilimpahi kelapangan rezeki dan kedamaian rumah tangga.',NULL),
(12,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Busana wajib bagi kedua mempelai pengantin pada saat upacara panggih (temu pengantin) adat Jawa. Mempelai pria dan wanita mengenakan motif yang serasi (sarimbit) sebagai simbol persatuan dua jiwa menuju mahligai kemakmuran.',NULL),
(12,'karakteristik',1,'Anatomi Visual','Komposisi geometris wajik berulang yang dihiasi ornamen singgasana takhta, pohon hayat, sayap garuda, dan kupu-kupu dengan latar ukel canting yang sangat padat.',NULL),
(12,'karakteristik',2,'Ornamen Singgasana Takhta & Meru','Bentuk bangunan istana bertingkat melambangkan kedudukan terhormat dan rumah tangga yang kokoh.','Struktur Utama • Singgasana'),
(12,'karakteristik',3,'Sayap Garuda (Lar) & Kupu-Kupu','Simbol perlindungan keteguhan hati dan metamorfosis kebahagiaan hidup.','Isen Sakral Mukti'),
(12,'karakteristik',4,'Sogan Keemasan Berwibawa','Perpaduan warna soga cokelat kemerahan matang dan kuning keemasan kayu tegeran.','Warna Tradisi Sogan'),
(12,'karakteristik',5,'Latar Isen Ukel Canting Padat','Seluruh bidang kosong kain dipenuhi ukir ukel malam halus melambangkan rezeki melimpah.',NULL),
(12,'karakteristik',6,'Bingkai Kisi Belah Ketupat','Pola wajik geometris simetris menjaga keteraturan dan keseimbangan visual mori.',NULL),
(12,'karakteristik',7,'Ornamen Kupu-Kupu Sepasang','Sepasang kupu-kupu melambangkan kesetiaan cinta dan keharmonisan suami istri.',NULL),
(12,'karakteristik',8,'Aura Keagungan Pengantin','Tekstur sogan yang medhok memancarkan pesona anggun dan wibawa di pelaminan.',NULL),
(13,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Sidomulyo memancarkan kemuliaan hakiki yang lahir dari integritas moral, kedermawanan, dan keteguhan berbuat kebajikan. Motif ini mengajarkan bahwa kemuliaan (''mulyo'') sejati manusia tidak diukur dari kedudukan pangkat atau sanjungan manusia, melainkan dari kemampuannya menebar manfaat bagi semesta, berlaku adil, dan hidup dalam keridhaan Tuhan Yang Maha Esa.',NULL),
(13,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Berkembang di lingkungan Keraton Kasunanan Surakarta dan Kesultanan Yogyakarta sejak abad ke-18. Merupakan pilar penting dalam keluarga motif ''Sido'' yang diciptakan untuk mengiringi upacara-upacara sakral daur hidup manusia Jawa.',NULL),
(13,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Sido'' (menjadi, terlaksana, atau langgeng) dan ''Mulyo'' (mulia, terhormat, disegani karena kebajikan, dan berbahagia). Mengandung doa restu agar pemakainya dilimpahi kemuliaan derajat budi pekerti, dijauhkan dari kehinaan moral, dan senantiasa diberkahi keselamatan lahir batin.',NULL),
(13,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Dikenakan oleh kedua mempelai dalam upacara pernikahan adat Jawa, serta dikenakan oleh orang tua dan sesepuh keluarga dalam prosesi siraman dan tingkeban (tujuh bulanan kehamilan) sebagai doa kemuliaan bagi keturunan yang akan lahir.',NULL),
(13,'karakteristik',1,'Anatomi Visual','Komposisi geometris wajik berulang yang memuat empat elemen ornamen utama secara berselang-seling dalam tatanan kisi simetris.',NULL),
(13,'karakteristik',2,'Empat Ornamen Kosmik Berselang-Seling','Pohon hayat, sayap garuda (lar), bangunan pura/joglo, dan kupu-kupu tersusun rapi.','Struktur Utama • Empat Kosmik'),
(13,'karakteristik',3,'Isen Cecek Pitu & Sawut Halus','Titik cecek tujuh dan garis sawut lembut mengisi setiap sudut bidang ornamen wajik.','Isen Canting Halus'),
(13,'karakteristik',4,'Pewarnaan Sogan Medhok Tradisi','Cokelat soga matang kemerahan berpadu hitam malam pekat dan dasar gading mori.','Warna Klasik Sogan'),
(13,'karakteristik',5,'Keteraturan Kisi Wajik Simetris','Bidang belah ketupat membagi bentangan kain dalam proporsi yang sangat teratur.',NULL),
(13,'karakteristik',6,'Garis Kontur Halus Berwibawa','Tarikan lilin malam canting nomor satu menjaga ketajaman lekuk ornamen pura dan lar.',NULL),
(13,'karakteristik',7,'Kerapatan Isen Latar Seimbang','Latar bidang kain diisi taburan cecek halus memberikan tekstur visual yang teduh.',NULL),
(13,'karakteristik',8,'Harmonisasi Empat Elemen Alam','Menggambarkan keselarasan tanah, api, angin, dan air dalam kehidupan manusia.',NULL),
(14,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Singa Barong memancarkan kekuatan kedaulatan, ketegasan memimpin, serta puncak toleransi persaudaraan antar bangsa. Figur satwa mitologi hibrida gabungan empat makhluk agung mengajarkan bahwa kemuliaan sebuah peradaban berakar dari kemampuannya merangkul keberagaman budaya, agama, dan etnis ke dalam satu kesatuan tekad menjaga kedamaian semesta.',NULL),
(14,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan di lingkungan Keraton Kasepuhan Cirebon pada abad ke-16 oleh Panembahan Losari. Terinspirasi langsung dari bentuk mahakarya Kereta Kencana Singa Barong karya Pangeran Losari pada tahun 1549 yang menjadi kereta pusaka kebesaran Sultan Cirebon.',NULL),
(14,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Menggabungkan empat unsur peradaban dunia: kepala naga (kebijaksanaan budaya Tionghoa/Buddha), badan gajah berbelalai memegang trisula (kekuatan budaya India/Hindu), tubuh singa perkasa (keberanian budaya Jawa/Nusantara), dan sepasang sayap garuda/buroq (keagungan budaya Islam/Timur Tengah). Melambangkan keutuhan persatuan umat manusia.',NULL),
(14,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Dahulu dikenakan secara eksklusif oleh para Sultan dan pembesar Keraton Kasepuhan serta Kanoman Cirebon dalam upacara penobatan tahta, iring-iringan upacara adat Panjang Jimat, serta resepsi kenegaraan menyambut duta kerajaan asing.',NULL),
(14,'karakteristik',1,'Anatomi Visual','Komposisi figuratif mitologis megah berpusat pada sosok satwa Singa Barong yang melangkah gagah di antara ornamen bebatuan wadasan dan mega mendung.',NULL),
(14,'karakteristik',2,'Satwa Mitologi Hibrida Singa Barong','Kepala naga bertanduk, belalai gajah memegang trisula, tubuh singa, dan bersayap garuda.','Struktur Utama • Satwa Sakral'),
(14,'karakteristik',3,'Bebatuan Wadasan & Awan Mendung','Ornamen batu karang tebing wadasan kokoh dan awan mendung mengelilingi figur satwa.','Ornamen Khas Cirebon'),
(14,'karakteristik',4,'Pewarnaan Sogan Pesisir Berwibawa','Paduan warna cokelat soga tua, hitam malam, dan dasar kain putih gading mori prima.','Warna Tradisi Keraton'),
(14,'karakteristik',5,'Senjata Trisula pada Belalai','Ujung belalai menggenggam senjata trisula melambangkan ketegasan menegakkan keadilan.',NULL),
(14,'karakteristik',6,'Canting Cecek Sisik & Bulu','Goresan titik canting halus merinci sisik naga dan bulu surai singa secara hidup.',NULL),
(14,'karakteristik',7,'Sayap Garuda Mengembang Megah','Sepasang sayap buruq terbentang lebar memancarkan aura perlindungan agung.',NULL),
(14,'karakteristik',8,'Keseimbangan Ruang Berkarakter','Tata letak figur satwa diimbangi oleh bidang wadasan yang kokoh dan dinamis.',NULL),
(15,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Srikaton merepresentasikan pancaran pesona batin yang berseri-seri, keanggunan pekerti yang menenteramkan pandangan, serta kewibawaan yang lahir dari ketulusan hati. Sebagaimana dewi kemakmuran yang memancarkan berkah, motif ini mengajarkan bahwa keindahan sejati seorang manusia terletak pada kemampuannya membawa keteduhan, bersikap santun, dan memancarkan wibawa kebaikan di mana pun ia berada.',NULL),
(15,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan oleh para maestro abdi dalem pembatik Keraton Kasunanan Surakarta Hadiningrat. Didesain secara khusus untuk mempercantik busana para putri keraton dan permaisuri dalam menghadiri upacara-upacara agung penyambutan tamu kehormatan istana.',NULL),
(15,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Sri'' (cahaya kemilau, keindahan, keagungan dewi padi, dan kemakmuran) serta ''Katon'' (tampak jelas, bercahaya, berseri, dan memancarkan aura). Mengandung doa agar pemakainya tampak berseri-seri wajah dan hatinya, disenangi oleh banyak orang, serta disegani karena keluhuran martabatnya.',NULL),
(15,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara tradisional dikenakan oleh para putri dan keluarga bangsawan keraton Surakarta dalam upacara pasowanan agung, perayaan hari besar istana, serta upacara pernikahan adat sebagai busana kebesaran yang memancarkan aura pesona pengantin.',NULL),
(15,'karakteristik',1,'Anatomi Visual','Komposisi ornamen klasik simetris yang tertata anggun, menampilkan gubahan kuncup bunga bermahkota megah yang diselingi sayap garuda mini dan sulur dedaunan.',NULL),
(15,'karakteristik',2,'Mahkota Bunga Kemilau Berseri','Gubahan kuncup bunga bermahkota anggun di tengah bidang geometris simetris.','Struktur Utama • Mahkota Sri'),
(15,'karakteristik',3,'Sayap Garuda Mini & Lidah Api','Ornamen lar garuda penjaga wibawa dan lidah api semangat hidup berkebajikan.','Isen Sakral Wibawa'),
(15,'karakteristik',4,'Pewarnaan Sogan Hangat Solo','Kombinasi warna cokelat soga matang kemerahan, kuning oker tegeran, dan dasar gading mori.','Warna Tradisi Keraton'),
(15,'karakteristik',5,'Susunan Kisi Tertib Anggun','Tata letak ornamen tersusun dalam irama yang seimbang, tenang, dan harmonis.',NULL),
(15,'karakteristik',6,'Canting Cecek Sawut Bergelombang','Larik-larik sawut halus menghiasi kelopak bunga memberi kesan merekah semerbak.',NULL),
(15,'karakteristik',7,'Isen Ukel Latar Lembut','Latar mori dihiasi ukel canting malam yang lembut dan mengalir tanpa patahan.',NULL),
(15,'karakteristik',8,'Proporsi Estetika Feminin Ningrat','Skala ornamen dirancang anggun dan proporsional untuk memancarkan aura kecantikan.',NULL),
(16,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Tribusono memancarkan keutuhan kesempurnaan etika hidup manusia yang memadukan keindahan lahiriah dan kesucian batiniah. Motif ini mengajarkan bahwa kesempurnaan seorang insan terletak pada keselarasan tiga dimensi pakaian batin: keanggunan tata krama raga di hadapan sesama, kebersihan jiwa dari dengki dan iri hati, serta keluhuran budi pekerti dalam mengabdi kepada Sang Maha Pencipta.',NULL),
(16,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan dan berkembang di lingkungan para perajin abdi dalem Keraton Surakarta dan Yogyakarta pada abad ke-18. Menjadi motif busana resmi dalam perhelatan ritual adat dan upacara pasowanan agung para ksatria keraton.',NULL),
(16,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Tri'' (tiga) dan ''Busono'' (busana, perhiasan, atau tatanan etika hidup). Mengandung ajaran moral bahwa manusia sejati wajib mengenakan tiga lapis busana batin: Busana Raga (kesopanan lahiriah), Busana Jiwa (kejujuran dan ketulusan batin), serta Busana Budi (kebijaksanaan, ilmu kebajikan, dan ketaatan kepada Tuhan).',NULL),
(16,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara tradisional dikenakan oleh para bangsawan, tetua adat, dan ksatria dalam menghadiri pertemuan penting musyawarah keraton, upacara daur hidup keluarga, serta busana jarik kebesaran dalam upacara adat Jawa.',NULL),
(16,'karakteristik',1,'Anatomi Visual','Komposisi ornamen klasik simetris berulang yang membagi bidang kain ke dalam tiga gugusan ragam hias utama yang berpadu harmonis.',NULL),
(16,'karakteristik',2,'Tiga Gugusan Ornamen Utama','Tiga kelompok ornamen flora berdaun tiga, sulur paku-pakuan, dan ornamen geometris.','Struktur Utama • Tiga Gugusan'),
(16,'karakteristik',3,'Sulur Paku & Isen Sawut Lembut','Garis lengkung sulur merambat dihiasi larik-larik sawut halus canting nomor satu.','Isen Canting Halus'),
(16,'karakteristik',4,'Pewarnaan Sogan Klasik Keraton','Paduan cokelat soga tua matang, hitam malam pekat, dan dasar mori gading prima.','Warna Tradisi Sogan'),
(16,'karakteristik',5,'Keteraturan Tata Letak Simetris','Ornamen ditata dalam kisi-kisi seimbang mencerminkan ketertiban tiga pilar moral.',NULL),
(16,'karakteristik',6,'Canting Cecek Mikro Tiga Titik','Gubahan titik cecek tiga melambangkan kesatuan raga, jiwa, dan budi pekerti.',NULL),
(16,'karakteristik',7,'Garis Kontur Mulus Berwibawa','Tarikan malam lilin tidak terputus menjaga keutuhan aliran ornamen flora.',NULL),
(16,'karakteristik',8,'Aura Ketenangan & Kebijaksanaan','Palet sogan gelap memancarkan aura keteduhan jiwa yang matang dan bijaksana.',NULL),
(17,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Tujuh Rupa merupakan pesta visual sukacita pesisir yang merayakan kekayaan flora, fauna, dan keharmonisan hidup berdampingan antar bangsa. Kombinasi aneka warnanya yang sangat meriah (polikromatik) melambangkan kelapangan dada, kegembiraan jiwa, serta keyakinan bahwa di balik setiap kesulitan hidup senantiasa terbit pertolongan dan jalan keluar yang membahagiakan.',NULL),
(17,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Lahir dan berakar di Kota Pekalongan, sentra batik pesisiran paling produktif di Jawa Tengah. Berkembang sejak abad ke-19 melalui perjumpaan budaya yang dinamis antara para pedagang Tionghoa, saudagar Arab, bangsa Eropa, dan perajin bumiputera Jawa pesisir.',NULL),
(17,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Kata ''Tujuh'' dikaitkan dengan falsafah Jawa ''Pitu'' yang bermakna ''Pitulungan'' (pertolongan dan keselamatan ilahi), sekaligus mengacu pada perpaduan tujuh warna kehidupan semesta. Kehadiran burung, kupu-kupu, dan bunga-bunga tropis melambangkan kebebasan jiwa yang senantiasa menebar keindahan bagi sesama manusia.',NULL),
(17,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Batik Tujuh Rupa sangat fleksibel dan digemari luas sebagai kain sarung perempuan, selendang kebaya perayaan pesta, busana tari tradisional pesisir, serta busana formal ceria dalam perhelatan budaya daerah.',NULL),
(17,'karakteristik',1,'Anatomi Visual','Komposisi naturalis meriah yang memadukan aneka macam bunga mekar, dedaunan rimbun, burung terbang, dan kupu-kupu dengan palet warna yang sangat kaya.',NULL),
(17,'karakteristik',2,'Flora Mekar & Kupu-Kupu Tropis','Rangkaian bunga teratai, mawar, dan krisan dikelilingi kupu-kupu dan burung.','Struktur Utama • Flora Meriah'),
(17,'karakteristik',3,'Isen Sawut Canting & Cecek Byur','Latar kain dipenuhi taburan cecek halus dan garis sawut melengkung yang rapat.','Isen Pesisiran Rapat'),
(17,'karakteristik',4,'Kekayaan Tujuh Warna Polikromatik','Paduan merah menyala, hijau pupus, biru toska, kuning mentega, dan ungu lembayung.','Warna Polikromatik Pesisir'),
(17,'karakteristik',5,'Tata Letak Bebas Asimetris','Gubahan ornamen ditata dinamis mengalir melintasi kain tanpa sekat geometris kaku.',NULL),
(17,'karakteristik',6,'Teknik Colet Kuas Halus','Kelopak bunga dan sayap kupu-kupu diberi warna gradasi cerah menggunakan kuas kecil.',NULL),
(17,'karakteristik',7,'Garis Kontur Tipis Mengalir','Goresan lilin malam ditarik dengan lincah mencerminkan kebebasan pesisiran.',NULL),
(17,'karakteristik',8,'Kepala Sarung Bertumpal Bunga','Ujung kain sarung dihiasi tumpal segitiga berhias burung merak yang elok.',NULL),
(19,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Wahyu Tumurun memancarkan harapan spiritual yang khusyuk akan turunnya bimbingan petunjuk, rahmat kemakmuran, dan kedudukan mulia dari Tuhan Yang Maha Esa. Motif ini mengajarkan bahwa anugerah kepemimpinan atau kebahagiaan hidup bukanlah sesuatu yang direbut dengan keserakahan, melainkan rahmat ilahi yang turun kepada insan yang senantiasa menjaga kesucian hati, berbuat adil, dan giat berikhtiar laku prihatin.',NULL),
(19,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan di lingkungan Keraton Yogyakarta dan Surakarta sejak abad ke-18 era Mataram Islam. Sering dikenakan dalam peristiwa sakral seperti upacara jumenengan (penobatan raja), pelantikan abdi dalem berprestasi, serta prosesi sakral pernikahan adat Jawa.',NULL),
(19,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Wahyu'' (anugerah, petunjuk, berkah, atau kemuliaan ilahi) dan ''Tumurun'' (turun mengalir dari langit). Mengandung doa permohonan yang mendalam agar pemakainya dikaruniai petunjuk kebenaran, kelancaran rezeki yang berkah, kedudukan terhormat yang amanah, serta keharmonisan langgeng dalam berumah tangga.',NULL),
(19,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Dikenakan oleh kedua mempelai dalam upacara panggih pernikahan adat Jawa, serta dikenakan oleh para pemimpin dan abdi dalem keraton dalam upacara wisuda kebesaran, pelantikan jabatan, dan doa selamatan kenegaraan.',NULL),
(19,'karakteristik',1,'Anatomi Visual','Komposisi ornamen klasik simetris dalam bidang kisi-kisi teratur yang memadukan mahkota terbang, sayap garuda, sepasang burung merak berhadapan, dan sulur bunga.',NULL),
(19,'karakteristik',2,'Mahkota Terbang Mustika Keraton','Bentuk mahkota kerajaan terbang bermahkota permata melambangkan kemuliaan anugerah tahta.','Struktur Utama • Mahkota'),
(19,'karakteristik',3,'Sayap Garuda (Lar) & Sepasang Burung','Sepasang sayap garuda perkasa dan burung merak berhadapan menyimbolkan perlindungan dan cinta.','Isen Sakral Wahyu'),
(19,'karakteristik',4,'Pewarnaan Sogan Matang Keraton','Dominasi warna cokelat soga tua jambal kemerahan, hitam malam pekat, dan dasar gading mori.','Warna Tradisi Sogan'),
(19,'karakteristik',5,'Pola Kisi Geometris Berulang','Susunan bidang ornamen ditata dalam keteraturan simetris yang mencerminkan ketertiban kosmos.',NULL),
(19,'karakteristik',6,'Canting Cecek Sawut Berwibawa','Larik-larik sawut halus menghiasi kelopak mahkota dan helai bulu sayap garuda.',NULL),
(19,'karakteristik',7,'Isen Ukel & Sulur Bunga Mekar','Sulur-sulur tumbuhan merambat mengelilingi mahkota melambangkan rezeki yang terus bertumbuh.',NULL),
(19,'karakteristik',8,'Aura Keagungan & Kemuliaan','Komposisi ornamen memancarkan aura kepemimpinan yang berwibawa, teduh, dan amanah.',NULL),
(20,'sejarah_filosofi',1,'Hakikat & Simbol','Batik Wirasat memancarkan ketajaman mata batin, kearifan menimbang firasat kebajikan, serta wasiat luhur orang tua kepada anak cucunya dalam mengarungi gelombang kehidupan. Motif pusaka ini mengajarkan bahwa bekal terindah yang diwariskan leluhur bukanlah tumpukan emas permata semata, melainkan nasihat kebijaksanaan hidup, ketajaman nurani membedakan kebaikan dari kebatilan, serta keteguhan memegang amanah leluhur.',NULL),
(20,'sejarah_filosofi',2,'Asal Daerah & Sejarah','Diciptakan dan dilestarikan secara turun-temurun di lingkungan Keraton Kasunanan Surakarta dan Kesultanan Yogyakarta sejak era Mataram Islam. Sering dikenakan bersama motif Truntum oleh orang tua pengantin pada prosesi sakral pernikahan adat Jawa.',NULL),
(20,'sejarah_filosofi',3,'Makna Filosofis Simbolik','Berasal dari kata ''Wirasat'' atau ''Firasat'' yang bermakna kepekaan batin, petunjuk nurani, dan wasiat nasihat orang tua. Mengandung doa restu agar pemakainya dikaruniai ketajaman mata hati, dijauhkan dari marabahaya fitnah duniawi, dan senantiasa teguh menapaki jalan kebenaran yang diridhai Tuhan.',NULL),
(20,'sejarah_filosofi',4,'Penggunaan Tradisional & Pakem','Secara tradisional dikenakan oleh orang tua mempelai pengantin, tetua adat, dan sesepuh keraton pada upacara pernikahan adat Jawa, upacara mitoni tingkeban, serta upacara ruwatan tolak bala sebagai permohonan keselamatan bagi keluarga besar.',NULL),
(20,'karakteristik',1,'Anatomi Visual','Komposisi geometris wajik yang memadukan kompilasi aneka ornamen motif pusaka keraton ke dalam bidang-bidang kisi teratur yang harmonis.',NULL),
(20,'karakteristik',2,'Gabungan Ornamen Pusaka Pilihan','Memadukan ornamen cakar ayam (kemandirian mencari nafkah), lidah api, truntum, dan sulur obat.','Struktur Utama • Multi Pusaka'),
(20,'karakteristik',3,'Ornamen Cakar Ayam & Lung Tanaman','Simbol kemandirian mencari nafkah halal dan sulur tanaman obat penolak bala.','Isen Sakral Wirasat'),
(20,'karakteristik',4,'Pewarnaan Sogan Klasik Keraton','Dominasi warna cokelat soga tua jambal kemerahan, hitam malam pekat, dan dasar gading mori.','Warna Tradisi Sogan'),
(20,'karakteristik',5,'Pola Kisi Belah Ketupat Tertib','Bidang wajik membagi ragam motif pusaka dalam keteraturan simetris yang khusyuk.',NULL),
(20,'karakteristik',6,'Canting Cecek Sawut Halus','Titik cecek dan garis sawut lembut mengisi setiap sudut bidang ornamen dengan teliti.',NULL),
(20,'karakteristik',7,'Garis Kontur Pembatas Anggun','Garis lilin malam memisahkan tiap ragam motif pusaka secara rapi dan tegas.',NULL),
(20,'karakteristik',8,'Aura Perlindungan & Nasihat Leluhur','Komposisi memancarkan keteduhan doa orang tua penuntun keselamatan anak cucu.',NULL)
)
