INSERT OR IGNORE INTO module_gallery_images (module_id, image_url, caption, order_no)
SELECT m.id, NULL, v.caption, v.order_no
FROM v JOIN modules m ON m.order_no = v.mod;

-- Soal tambahan untuk melengkapi bank soal menjadi 25 soal per modul (Total 500 soal)
WITH v(mod, question, a, b, c, d, correct, explanation) AS (VALUES
(1,'Dari manakah daerah asal utama berkembangnya motif Batik Betawi?','DKI Jakarta (Batavia)','Surakarta Hadiningrat','Cirebon Jawa Barat','Pekalongan Jawa Tengah','A','Batik Betawi lahir dan berkembang di wilayah Jakarta seperti Palmerah dan Karet.'),
(1,'Ikon budaya manakah yang paling sering menjadi ciri khas utama Batik Betawi?','Ondel-ondel dan Tugu Monas','Candi Borobudur','Burung Garuda Meru','Kereta Singa Barong','A','Ondel-ondel dan Monas adalah lambang khas budaya serta sejarah ibu kota.'),
(1,'Nilai filosofis apa yang terkandung dalam motif Ondel-ondel pada Batik Betawi?','Penolak bala dan penjaga ketenteraman warga','Simbol kesedihan masa lalu','Tanda peperangan antar suku','Lambang pencarian harta karun','A','Ondel-ondel dipercaya sebagai penolak mara bahaya dan pelindung ketenteraman kampung.'),
(1,'Batik Betawi banyak dipengaruhi oleh akulturasi berbagai bangsa, salah satunya...','Tionghoa, Arab, Melayu, dan Eropa','Yunani Kuno dan Persia','Jepang Zaman Edo','Suku Maya dan Inka','A','Batavia sebagai kota pelabuhan internasional mempertemukan etnis Melayu, Tionghoa, Arab, dan Eropa.'),
(1,'Bagaimanakah karakter palet warna yang mendominasi Batik Betawi?','Warna cerah, menyala, dan kontras berani','Hanya hitam dan putih polos','Cokelat soga gelap keraton','Abu-abu monokrom lembut','A','Batik Betawi identik dengan warna cerah seperti merah, kuning, dan hijau yang mencerminkan keceriaan.'),
(1,'Apakah arti simbolik dari motif Kembang Kelapa pada Batik Betawi?','Kemakmuran, kemeriahan pesta, dan keberkahan hidup','Tanda kedukaan keluarga','Lambang kesunyian malam','Simbol musim kemarau panjang','A','Kembang kelapa menyimbolkan kemeriahan, kemakmuran, dan pohon serbaguna yang bermanfaat bagi sesama.'),
(1,'Kawasan manakah di Batavia yang dahulu terkenal sebagai sentra pembatikan Betawi?','Palmerah, Karet Tengsin, dan Kebayoran Lama','Pantai Parangtritis','Kawasan Malioboro','Pasar Klewer Surakarta','A','Palmerah dan Karet Tengsin merupakan pusat perajin batik Betawi tempo dulu.'),
(1,'Bagian tepi kain sarung Betawi yang berhias segitiga runcing disebut...','Tumpal atau pucuk rebung','Mlinjon','Lar garuda','Ukel canting','A','Tumpal berpola pucuk rebung merupakan hiasan wajib di kepala sarung batik Betawi.'),
(1,'Apa makna filosofis ornamen Pucuk Rebung pada kain Batik Betawi?','Pertumbuhan budi pekerti luhur dan cita-cita tinggi','Ketakutan akan badai','Perpisahan abadi','Kelemahan fisik manusia','A','Pucuk rebung bambu yang selalu tumbuh menjulang melambangkan harapan masa depan yang kokoh.'),
(1,'Pada acara adat apakah busana Batik Betawi umumnya wajib dikenakan?','Pernikahan adat Betawi dan upacara Palang Pintu','Upacara Sekaten Keraton','Tingkeban adat Solo','Labuhan laut selatan','A','Batik Betawi menjadi busana kebesaran adat perkawinan dan tradisi palang pintu Betawi.'),
(1,'Burung apakah yang sering diadaptasi dari pengaruh Tionghoa pada Batik Betawi?','Burung Hong (Phoenix)','Burung Enggang','Burung Merak Soga','Burung Cendrawasih','A','Burung Hong melambangkan keanggunan, cinta kasih, dan keberuntungan.'),
(1,'Bagaimanakah susunan motif pada Batik Betawi jika dibandingkan batik pedalaman?','Lebih bebas, ekspresif, dan tidak terikat aturan keraton','Sangat kaku berlereng 45 derajat','Harus geometris simetris empat arah','Selalu bermotif binatang air laut','A','Batik Betawi bergaya pesisiran bebas dan spontan mengekspresikan kehidupan sehari-hari.'),
(1,'Bahan kain katun mori apakah yang lazim dipakai untuk membatik tulis halus?','Mori Primissima','Kain Goni Kasar','Kain Terpal Sintetis','Kain Denim Jeans','A','Mori Primissima adalah jenis katun terbaik dengan anyaman serat paling rapat.'),
(1,'Apakah fungsi canting dalam proses pembuatan Batik Betawi tulis?','Menorehkan cairan lilin malam panas pada pola mori','Memotong kain sesuai pola busana','Mengaduk pewarna kimia di ember','Menghaluskan serat kain mori','A','Canting berfungsi sebagai pena lilin untuk menggambar motif secara manual.'),
(1,'Mengapa warna Batik Betawi cenderung berani dan kontras?','Mencerminkan karakter masyarakat Betawi yang ceria dan terbuka','Karena kekurangan bahan pewarna alami','Mengikuti perintah penguasa kolonial','Agar kain cepat kering di bawah terik','A','Karakter warga Betawi yang spontan, hangat, dan egaliter tercermin dalam warna-warna cerah.'),
(1,'Motif Sungai Ciliwung pada Batik Betawi membawa pesan ekologis berupa...','Pentingnya menjaga kelestarian dan kebersihan sumber air','Anjuran membangun bendungan raksasa','Peringatan bahaya perdagangan laut','Larangan berlayar saat malam','A','Motif Ciliwung mengingatkan masyarakat untuk merawat sungai sebagai urat nadi kehidupan.'),
(1,'Siapakah yang sering mengenakan kain sarung batik Betawi dalam busana harian pria?','Para kaum lelaki Betawi yang dipadukan baju koko/sadariah','Hanya anak balita keraton','Para prajurit berkuda Mataram','Hanya penari istana','A','Kain sarung batik dikalungkan atau dililitkan di pinggang oleh pria Betawi bersama baju sadariah.'),
(1,'Batik Betawi termasuk dalam rumpun gaya batik...','Batik Pesisiran','Batik Keraton Klasik','Batik Pedalaman Vorstenlanden','Batik Monokromatis','A','Secara kultural dan geografis, Batik Betawi tergolong dalam rumpun batik pesisir.'),
(1,'Teknik menutupi bagian kain tertentu dengan lilin malam disebut proses...','Malam atau membatik (nglowongi/nembok)','Mordan benang','Pengeringan angin','Penenunan benang pakan','A','Prinsip dasar batik adalah perintang warna menggunakan lilin malam cair.'),
(1,'Istilah melepas atau meluruhkan lilin malam dari kain mori dengan air mendidih disebut...','Nglorod','Medel','Nyungging','Njaplak','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(1,'Salah satu flora Jakarta yang diangkat menjadi motif batik Betawi adalah...','Salak Condet dan Sirih Kuning','Bunga Sakura','Pohon Kurma Padang Pasir','Tanaman Gandum','A','Salak Condet dan Sirih Kuning adalah flora endemik bersejarah kota Jakarta.'),
(2,'Apa arti kata ''Kencono'' dalam bahasa Jawa yang disematkan pada motif ini?','Emas yang berkilau mulia','Batu karang samudera','Bunga melati harum','Angin sejuk pegunungan','A','Kencono dalam bahasa Jawa bermakna emas murni berlambang kemuliaan.'),
(2,'Bokor dalam tradisi keraton Jawa adalah piranti berbentuk...','Wadah atau mangkuk besar berukir dari logam','Senjata keris berlekuk sembilan','Topeng penutup wajah raja','Kereta kuda kencana','A','Bokor adalah bejana atau mangkuk logam tempat tirta suci atau bunga upacara.'),
(2,'Pesan moral utama yang terkandung dalam filosofi Batik Bokor Kencono adalah...','Menyiapkan hati yang suci untuk menampung berkah dan berbuat kebajikan','Mengumpulkan kekayaan duniawi sebanyak mungkin','Menghindari pergaulan dengan masyarakat umum','Menonjolkan kekuatan fisik dalam pertarungan','A','Bokor Kencono mengajarkan manusia agar memiliki hati seluas bejana penampung kebaikan.'),
(2,'Dari manakah lingkungan asal penciptaan Batik Bokor Kencono?','Keraton Kasunanan Surakarta Hadiningrat','Pesisir Pelabuhan Cirebon','Pedalaman Dayak Kalimantan','Kawasan Pecinan Lasem','A','Bokor Kencono merupakan motif klasik keraton Surakarta Hadiningrat.'),
(2,'Apakah fungsi ornamen Lung-lungan yang menghiasi bejana Bokor Kencono?','Melambangkan kelangsungan hidup dan rezeki yang terus merambat tumbuh','Menunjukkan batas wilayah kerajaan','Simbol kesedihan panen gagal','Tanda berakhirnya sebuah dinasti','A','Lung-lungan sulur tumbuhan menyimbolkan kesinambungan hidup dan rezeki yang tak pernah putus.'),
(2,'Warna klasik apakah yang menjadi ciri utama motif Bokor Kencono?','Cokelat soga, hitam malam, dan dasar gading','Merah menyala darah ayam','Kuning neon dan jingga muda','Hijau toska mencolok','A','Sogan klasik khas Solo mendominasi motif keagungan keraton ini.'),
(2,'Pohon apakah yang kulit batangnya dimanfaatkan untuk menghasilkan zat warna cokelat soga?','Pohon Soga Jambal (Peltoforumpterocarpum)','Pohon Jati Belanda','Pohon Kelapa Sawit','Pohon Pinus Gunung','A','Kulit soga jambal merupakan bahan utama pewarnaan cokelat alami batik klasik.'),
(2,'Bagaimanakah susunan geometris motif Bokor Kencono pada sehelai kain?','Tertata rapi dalam kisi-kisi berulang yang simetris','Miring berlereng tajam 45 derajat tanpa jeda','Berantakan secara acak dan bebas','Membentuk segitiga tunggal di tengah','A','Motif Bokor Kencono tersusun dalam pola kisi-kisi teratur dan simetris.'),
(2,'Apakah makna simbolik dari isen titik ''Cecek Pitu'' yang kerap menyertai motif ini?','Pitulungan atau permohonan pertolongan kepada Tuhan','Tujuh samudera luas di bumi','Tujuh prajurit berkuda pengawal','Tujuh lapis kain pelindung','A','Pitu berarti tujuh, melambangkan pitulungan (pertolongan dan berkah ilahi).'),
(2,'Kapan momentum adat yang tepat untuk mengenakan kain batik Bokor Kencono?','Upacara pisowanan keraton dan resepsi pernikahan adat','Saat melaut mencari ikan','Ketika berolahraga panahan','Saat beristirahat di malam hari','A','Kain ini dikenakan pada upacara agung, pertemuan resmi, dan pernikahan adat.'),
(2,'Batik Bokor Kencono mencerminkan harapan agar pemakainya dikaruniai...','Kemakmuran, martabat terhormat, dan kebijaksanaan hidup','Kemenangan mutlak dalam perang saudara','Kekuasaan yang ditakuti semua orang','Kesempatan berlayar ke negeri barat','A','Bokor Kencono melambangkan kemakmuran, budi luhur, dan keluhuran martabat.'),
(2,'Alat canting dengan cucuk (corong) paling kecil digunakan khusus untuk...','Membuat isen cecek dan sawut yang sangat halus','Mengisi bidang blok lilin yang luas (nembok)','Mencelup kain ke dalam bejana pewarna','Mengikis lilin dari permukaan kain mori','A','Canting cecek cucuk mikro digunakan untuk membuat titik-titik ornamen halus.'),
(2,'Bahan baku lilin malam batik tradisional terbuat dari campuran...','Gondorukem, damar, dan lilin lebah (malam lebah)','Semen putih dan minyak goreng','Tepung tapioka dan getah karet','Pewarna tekstil dan air cuka','A','Lilin malam diramu dari gondorukem, damar mata kucing, dan lilin lebah.'),
(2,'Ciri khas ragam hias keraton Surakarta dibandingkan Yogyakarta adalah...','Warna sogan cenderung kecokelatan hangat dan ornamen lebih luwes','Dasar kain selalu putih bersih menyala','Hanya menggunakan garis lurus tanpa lengkungan','Tidak pernah menggunakan ornamen tumbuhan','A','Batik Solo berkarakter soga cokelat hangat kekuningan dengan motif lembut luwes.'),
(2,'Bokor Kencono melambangkan derajat ksatria yang diukur dari...','Kelapangan dada menampung ujian dan memberi manfaat bagi sesama','Jumlah tanah kekuasaan yang dimiliki','Banyaknya selir di istana','Ketajaman bilah senjata pusaka','A','Keluhuran derajat sejati terletak pada kemurahan hati dan manfaat bagi orang banyak.'),
(2,'Proses menutup bidang latar putih kain agar tidak terkena warna dinamakan...','Nembok','Nglorod','Nyorek','Ngasah','A','Nembok adalah proses memblok bagian kain dengan malam tebal agar tidak terserap zat warna.'),
(2,'Tanaman apakah yang digunakan untuk memberi nuansa warna biru alami pada batik klasik?','Daun Tarum / Nila (Indigofera)','Biji Kesumba Keling','Kulit Buah Manggis','Akar Wangi Lerak','A','Daun nila (Indigofera) menghasilkan zat warna biru alami (wedelan).'),
(2,'Bokor Kencono termasuk motif yang sarat dengan ajaran...','Hastabrata dan kepemimpinan luhur Jawa','Perdagangan bebas antar benua','Teknik bertani di rawa pesisir','Pembuatan kapal perang kayu','A','Motif ini menyiratkan ajaran watak kepemimpinan luhur dan pengendalian budi batin.'),
(2,'Dalam tata busana pria keraton, kain batik dikenakan sebagai bebet (jarik) dengan lipatan...','Wiron di bagian depan','Kancing di sisi samping','Tali pengikat di leher','Rumbai kain di pundak','A','Kain jarik dilipat secara wiron rapi di bagian depan busana adat.'),
(2,'Apakah fungsi air buah lerak dalam perawatan kain batik tulis halus?','Mencuci kain secara lembut tanpa merusak serat dan warna alami','Menghilangkan lapisan lilin malam tebal','Mempercepat pengeringan di bawah matahari','Mengubah warna kain menjadi mengilap','A','Buah lerak mengandung saponin alami yang aman merawat serat kain batik tulis.'),
(2,'Unsur flora apakah yang sering digubah di dalam bejana Bokor Kencono?','Kuncup bunga teratai (lotus) yang suci','Batang kaktus berduri','Bunga mawar merah berduri','Pohon kelapa sawit','A','Teratai melambangkan kesucian batin yang mekar indah di atas air.'),
