(9,'Ornamen belah ketupat mini yang mengisi sela-sela lereng motif Parang disebut...','Mlinjon','Ukel canting','Lar garuda','Cecek sawut','A','Mlinjon berbentuk belah ketupat melambangkan perisai batin dari godaan nafsu.'),
(9,'Kain mori jenis apakah yang merupakan katun terbaik dan paling rapat untuk membatik tulis halus?','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Parasut Tahan Air','A','Mori Primissima adalah mori bermutu tertinggi untuk membatik tulis halus.'),
(9,'Alat khas berparuh tembaga untuk menorehkan cairan lilin malam panas dinamakan...','Canting','Gawangan kayu','Bandul timah','Wajan anglo','A','Canting adalah pena perintang lilin malam utama dalam seni batik.'),
(9,'Teknik awal menggambar garis kerangka outline pola utama batik dinamakan proses...','Nglowongi','Nembok mori','Medel wedelan','Nglorod lilin','A','Nglowongi adalah proses membuat garis kerangka utama motif menggunakan canting.'),
(9,'Berapakah passing score kelulusan minimal pada platform Kenali Batikmu?','70 persen','50 persen','60 persen','80 persen','A','Standar kelulusan kuis teori maupun praktik Kenali Batikmu adalah 70 persen.'),
(9,'Parang Kusumo memiliki dimensi ukuran lidah sekitar...','3 sampai 4 sentimeter','10 sampai 15 sentimeter','1 milimeter mikro','20 sentimeter raksasa','A','Ukuran lidah parang kusumo adalah sekitar 3-4 cm, dikhususkan bagi keturunan ningrat.'),
(9,'Varian motif Parang berukuran paling besar (di atas 10 cm) yang dikhususkan bagi raja adalah...','Parang Rusak Barong','Parang Klitik','Parang Kusumo','Parang Pamor','A','Parang Barong adalah parang terbesar yang hanya boleh dikenakan oleh Raja/Sultan.'),
(9,'Varian motif Parang berukuran kecil halus yang dikenakan para putri keraton adalah...','Parang Klitik','Parang Barong','Parang Rusak Gede','Parang Curigo','A','Parang Klitik memiliki lidah halus dan lembut untuk para putri keraton.'),
(9,'Tiga warna sakral sogan yang mendominasi Parang Kusumo keraton adalah...','Cokelat soga tua, kuning oker, dan putih gading mori','Merah menyala, hijau toska, dan ungu','Hitam pekat, abu-abu, dan merah muda','Kuning neon dan biru terang','A','Tiga warna sogan klasik melambangkan keselarasan bumi, api, dan kesucian air.'),
(9,'Dalam adat pernikahan Jawa, kain Parang Kusumo lazim dikenakan pada saat upacara...','Tukar cincin lamaran dan akad nikah','Membajak sawah pengantin','Perjalanan melaut nelayan','Pesta ulang tahun anak','A','Parang Kusumo dikenakan saat lamaran tukar cincin sebagai doa keteguhan cinta.'),
(9,'Garis lereng yang tak pernah putus pada motif Parang melambangkan prinsip hidup...','Kesinambungan tekad, perjuangan tak kenal lelah, dan ikatan darah','Keinginan menguasai wilayah lain','Perpisahan abadi antar keluarga','Kelemahan batin manusia','A','Garis tanpa jeda melambangkan laku prihatin yang tiada henti demi kemuliaan budi.'),
(10,'Apakah arti harfiah dari nama motif Batik Sekar Jagad?','Kumpulan bunga-bunga keindahan alam semesta (dunia)','Pedang ksatria yang berkilau','Ombak laut yang menghantam karang','Awan mendung pembawa petir','A','Sekar berarti bunga mekar, dan Jagad berarti alam semesta atau dunia.'),
(10,'Bentuk pembagian bidang pada kain Batik Sekar Jagad menyerupai...','Bidang-bidang pulau pada peta atlas dunia yang berdampingan','Kotak papan catur kaku','Garis lurus vertikal sejajar','Satu lingkaran raksasa tunggal','A','Sekar Jagad tersusun atas bidang meliuk menyerupai pulau-pulau pada peta bumi.'),
(10,'Pesan filosofis utama yang tersirat dalam motif Sekar Jagad adalah...','Toleransi, persatuan dalam keberagaman, dan kedamaian semesta','Kemenangan mutlak atas lawan perang','Keinginan menguasai seluruh dunia','Rasa takut menghadapi masa depan','A','Sekar Jagad adalah lambang persatuan dalam keberagaman yang harmonis.'),
(10,'Dari manakah lingkungan tradisi asal berkembangnya Batik Sekar Jagad?','Keraton Surakarta dan Keraton Yogyakarta','Pesisir Madura Timur','Pedalaman Suku Baduy','Pesisir Pantai Bali','A','Sekar Jagad berkembang dari maestro pembatik keraton Surakarta dan Yogyakarta.'),
(10,'Apakah yang membedakan isi setiap bidang pulau pada kain Sekar Jagad?','Setiap pulau diisi dengan motif batik klasik yang berbeda-beda','Semua pulau memiliki gambar yang persis sama','Setiap pulau dibiarkan kosong tanpa warna','Hanya diisi tulisan huruf kuno','A','Keunikan Sekar Jagad adalah setiap pulau memuat ragam motif klasik berbeda.'),
(10,'Sebutkan contoh motif klasik yang sering dijumpai di dalam pulau Sekar Jagad!','Kawung, truntum, parang klitik, cecek sawut, dan lereng','Ondel-ondel dan monas','Naga liong dan buketan','Tameng mandau dan enggang','A','Pulau-pulau Sekar Jagad diisi cuplikan motif klasik keraton Jawa.'),
(10,'Garis putih tipis yang membatasi antar bidang pulau Sekar Jagad dinamakan...','Gegaran atau garis pembatas canting','Tumpal segitiga','Mlinjon wajik','Lar garuda','A','Garis batas mori (gegaran) memisahkan tiap pulau agar motif tidak bercampur.'),
(10,'Mengapa Batik Sekar Jagad tulis membutuhkan tingkat keahlian pembatik yang sangat tinggi?','Karena harus menguasai puluhan ragam isen-isen klasik dengan ketelitian canting ekstra','Karena dikerjakan sambil berdiri','Karena kainnya harus basah terus menerus','Karena tidak boleh menggunakan penerangan lampu','A','Pengerjaan aneka isen yang berbeda menuntut kemahiran dan ketelitian luar biasa.'),
(10,'Batik Sekar Jagad sangat lazim dikenakan dalam upacara pernikahan adat Jawa oleh...','Orang tua kedua mempelai pengantin','Para juru masak dapur pesta','Kusir kereta kuda pengantin','Anak-anak pembawa bunga','A','Orang tua pengantin mengenakan Sekar Jagad sebagai lambang kebesaran budi pekerti.'),
(10,'Warna klasik yang mendominasi Batik Sekar Jagad keraton adalah...','Cokelat sogan matang, hitam pekat, dan putih gading mori','Merah muda cerah dan ungu muda','Kuning terang neon','Hijau toska laut pesisiran','A','Palet warna sogan agung khas keraton mendominasi Sekar Jagad klasik.'),
(10,'Kata ''Kar'' pada Sekar Jagad oleh sebagian pemerhati budaya juga dikaitkan dengan bahasa Belanda ''Kaart'' yang bermakna...','Peta (Peta Dunia)','Kapal layar','Kuda tunggangan','Surat kabar','A','Kaart berarti peta, memperkuat tafsir Sekar Jagad sebagai peta pesona bunga dunia.'),
(10,'Doa apakah yang terkandung bagi pemakai kain Batik Sekar Jagad?','Memancarkan aura pesona luhur, berwibawa, dan disenangi banyak orang','Dapat mengalahkan musuh di medan laga','Menjadi saudagar kapal terkaya','Menghindar dari tanggung jawab sosial','A','Sekar Jagad dipercaya memancarkan daya tarik budi luhur bagi pemakainya.'),
(10,'Tingkat kerapatan motif pada Batik Sekar Jagad tulis halus tergolong...','Sangat rapat dan padat hampir tanpa ruang kosong (isen byur)','Sangat renggang dan banyak ruang kosong','Hanya satu ornamen di pojok bawah','Polos tanpa garis','A','Seluruh bidang kain dipenuhi rincian isen-isen canting secara teliti.'),
(10,'Teknik menorehkan cairan lilin malam pada kain mori menggunakan canting disebut...','Mencanting tulis','Menenun ikat','Menyulam benang wol','Mengukir pahat','A','Mencanting adalah teknik dasar pembatikan tulis menggunakan canting lilin.'),
(10,'Apakah fungsi isen ''Sawut'' yang kerap mengisi kelopak pulau Sekar Jagad?','Garis-garis lembut melengkung yang memberi efek gradasi dan tekstur daun','Titik bulat besar hitam','Bercak cairan kimia','Garis lurus kaku','A','Sawut berupa garis-garis lembut melengkung pemberi tekstur dan bayangan.'),
(10,'Bahan baku lilin malam yang digunakan untuk mencanting garis pembatas pulau harus memiliki sifat...','Ulet, daya lekat kuat, dan tidak mudah remuk/retak saat pewarnaan','Sangat cair seperti air tawar','Mudah rapuh saat tersentuh tangan','Cepat berasap tebal','A','Malam klowong pembatas harus liat dan kokoh agar tidak bocor diterobos warna.'),
(10,'Proses mencelup kain batik ke dalam larutan soga alami berulang kali bertujuan...','Mendapatkan kedalaman warna cokelat soga yang matang (medhok) dan rata','Menghapus gambar pola canting','Mengeraskan kain seperti papan','Membuat kain menjadi transparan','A','Pencelupan soga berulang kali menghasilkan warna cokelat keraton yang khas.'),
(10,'Batik Sekar Jagad membuktikan kekayaan intelektual leluhur Nusantara dalam...','Mengomposisikan keberagaman elemen visual menjadi karya seni yang indah dan harmonis','Meniru pola tekstil bangsa lain secara mentah','Membuat pakaian seragam militer','Menciptakan mesin cetak otomatis','A','Sekar Jagad adalah mahakarya seni tata rupa mozaik tingkat tinggi nusantara.'),
(10,'Dalam busana resmi wanita modern, kain Sekar Jagad sangat anggun berpadu dengan...','Kebaya beludru hitam berhias sulam emas atau kebaya brokat klasik','Kaos oblong olahraga','Jaket parasut bertudung','Rompi jeans kasual','A','Kain jarik Sekar Jagad berpadu anggun dengan kebaya beludru atau brokat klasik.'),
(10,'Bagian kain mori yang tidak terkena lilin malam saat proses pewarnaan akan...','Menyerap zat warna celup secara permanen','Tetap berwarna putih polos','Larut terbakar zat pewarna','Mengeras menjadi batu','A','Prinsip batik: bagian yang tidak tertutup lilin akan menyerap zat pewarna.'),
(10,'Pola Sekar Jagad juga mengajarkan kita bahwa perbedaan latar belakang manusia...','Dapat disatukan dalam bingkai kebersamaan yang indah saling menguatkan','Harus dihapuskan seluruhnya','Menjadi alasan untuk saling bermusuhan','Hanya boleh ada satu pendapat tunggal','A','Perbedaan latar motif yang bersatu menyimbolkan indahnya persaudaraan manusia.'),
(11,'Apakah arti kata ''Sido'' dalam bahasa Jawa yang menjadi awalan nama motif ini?','Menjadi, terlaksana, atau berkesinambungan','Berhenti atau selesai','Hilang atau lenyap','Terpecah belah','A','Sido bermakna menjadi, terlaksana, atau terwujud secara berkesinambungan.'),
(11,'Apakah arti kata ''Luhur'' pada motif Batik Sidoluhur?','Mulia, terhormat, tinggi derajat budi pekertinya','Kaya raya harta benda','Kuat otot dan fisiknya','Pandai berlayar jauh','A','Luhur bermakna berbudi pekerti mulia, terhormat, dan berakhlak terpuji.'),
(11,'Nilai filosofis utama apakah yang diajarkan oleh motif Batik Sidoluhur?','Keluhuran budi pekerti dan ketulusan hati lebih utama daripada tahta duniawi','Mengejar jabatan dengan segala cara','Menonjolkan kekayaan di depan umum','Menghindari tanggung jawab sosial','A','Sidoluhur menekankan bahwa derajat sejati manusia berakar dari kemuliaan akhlak.'),
(11,'Dari manakah lingkungan tradisi asal penciptaan motif Batik Sidoluhur?','Keraton Surakarta Hadiningrat dan Kesultanan Yogyakarta','Pesisir Utara Banten','Pedalaman Hutan Kalimantan','Pegunungan Tanah Toraja','A','Sidoluhur merupakan motif klasik keraton Mataram di Surakarta dan Yogyakarta.'),
(11,'Bentuk geometris apakah yang menjadi bingkai utama pembagi motif Sidoluhur?','Belah ketupat (wajik) yang tertata rapi simetris','Segitiga tajam berundak','Lingkaran konsentris acak','Garis lurus membujur vertikal','A','Kisi-kisi belah ketupat (wajik) membingkai setiap elemen ornamen Sidoluhur.'),
(11,'Ornamen sakral berbentuk gunung bertingkat tiga pada Sidoluhur dinamakan...','Meru','Mlinjon','Tumpal','Ukel','A','Meru melambangkan gunung suci tempat bersemayamnya keagungan dan keteguhan iman.'),
(11,'Apakah makna simbolik dari ornamen Meru (gunung) pada kain batik keraton?','Keteguhan iman kepada Tuhan dan tempat berlabuhnya doa keselamatan','Tanda bahaya letusan gunung berapi','Larangan bepergian ke hutan','Simbol kesedihan panen gagal','A','Meru menyimbolkan keteguhan iman, kekokohan prinsip, dan kemuliaan kosmis.'),
(11,'Ornamen sepasang sayap burung garuda pada motif Sidoluhur dinamakan...','Lar garuda','Sawat ageng','Mirong','Gegaran','A','Lar adalah sepasang sayap garuda lambang kekuasaan adil dan perlindungan Tuhan.'),
(11,'Kapan momentum upacara adat pernikahan Jawa saat kain Sidoluhur paling tepat dikenakan?','Saat upacara Panggih (temu pengantin)','Saat mencuci piring pesta','Saat membangun tenda pesta','Saat gladi resik beberapa minggu sebelumnya','A','Sidoluhur dikenakan saat prosesi sakral panggih temu mempelai pria dan wanita.'),
(11,'Doa restu apakah yang dipanjatkan saat pengantin mengenakan kain Sidoluhur?','Semoga kehidupan rumah tangganya senantiasa dilimpahi keluhuran derajat dan budi pekerti','Semoga segera menjadi saudagar kapal terkaya','Semoga ditakuti oleh seluruh warga kampung','Semoga sering memenangkan pertarungan fisik','A','Sidoluhur membawa doa agar pasangan pengantin menjadi pribadi yang mulia dan luhur.'),
(11,'Warna sakral apakah yang mendominasi kain Batik Sidoluhur klasik?','Cokelat sogan tua, hitam malam, dan dasar gading mori','Merah muda cerah dan biru muda','Kuning neon dan jingga terang','Hijau toska mencolok','A','Warna sogan klasik melambangkan keteduhan jiwa dan keagungan tradisi keraton.'),
(11,'Pohon mitologis apakah yang melambangkan berkah kesuburan dan rezeki pada Sidoluhur?','Pohon Hayat (Pohon Kehidupan / Kalpataru)','Pohon Kaktus Padang Pasir','Pohon Kelapa Sawit','Pohon Bambu Runcing','A','Pohon hayat melambangkan anugerah kehidupan dan kesuburan lahir batin.'),
(11,'Ornamen kupu-kupu yang beterbangan di dalam motif Sidoluhur menyimbolkan...','Metamorfosis kesempurnaan budi manusia dan keindahan cinta kasih','Hama perusak tanaman bunga','Pertanda musim paceklik','Ketidaksabaran dalam bekerja','A','Kupu-kupu melambangkan proses perubahan batin menuju kematangan budi luhur.'),
(11,'Bahan pewarna cokelat alami soga berasal dari campuran kulit pohon...','Soga jambal, kayu tegeran, dan kulit pohon tingi','Kulit buah durian masak','Daun pepaya pahit','Getah karet mentah','A','Soga jambal, tegeran, dan tingi merupakan formula klasik pewarna sogan keraton.'),
(11,'Alat canting dengan cucuk (paruh corong) halus berdiameter satu milimeter digunakan untuk...','Mencanting garis ornamen meru dan isen sawut','Mencelup kain ke dalam bejana soga','Menghapus lilin yang salah','Mengeringkan mori di jemuran','A','Canting klowong halus digunakan untuk menggambar outline ornamen sakral.'),
(11,'Apakah fungsi isen ''Cecek Pitu'' yang kerap menyertai motif Sidoluhur?','Sebagai lambang ''Pitulungan'' (permohonan pertolongan dan anugerah ilahi)','Sebagai penanda harga kain mori','Sebagai tanda kepemilikan abdi dalem','Sebagai pengingat jumlah hari dalam seminggu','A','Pitu berarti tujuh, menyimbolkan pitulungan (anugerah dan pertolongan Tuhan).'),
(11,'Kain batik Sidoluhur yang baik memiliki sifat lilin malam yang...','Tembus sempurna ke sisi belakang kain sehingga motif bolak-balik terlihat jelas','Hanya menempel tipis di permukaan atas saja','Mudah luntur saat dicuci air dingin','Berbau menyengat seperti bensin','A','Batik tulis bermutu tinggi memiliki tembusan lilin yang sempurna di kedua sisi mori.'),
(11,'Dalam tradisi daur hidup manusia Jawa, kain Sidoluhur juga dikenakan pada upacara...','Upacara Tingkeban (Mitoni tujuh bulanan kehamilan)','Upacara potong gigi balita','Upacara turun ke sawah pertama','Pesta perayaan kemenangan perang','A','Sidoluhur dikenakan saat mitoni mendoakan agar calon jabang bayi berakhlak luhur.'),
(11,'Mengapa pembuatan sehelai kain Sidoluhur tulis halus membutuhkan waktu 2 hingga 3 bulan?','Karena kerumitan merinci ornamen sakral, isen sawut, dan proses pencelupan soga berulang kali','Karena perajin hanya bekerja seminggu sekali','Karena menunggu musim hujan reda','Karena mori harus dijemur di puncak gunung','A','Ketelitian canting dan pewarnaan berlapis membutuhkan ketekunan berbulan-bulan.'),
(11,'Ornamen bangunan rumah panggung kecil yang sering menyertai motif Sidoluhur disebut...','Pura atau singgasana takhta','Kandang merpati','Gudang padi lumbung','Benteng pertahanan','A','Singgasana pura melambangkan ketenteraman dan keharmonisan istana rumah tangga.'),
(11,'Batik Sidoluhur termasuk dalam kelompok motif yang tidak boleh...','Dipakai untuk alas tidur atau keset kaki sembarangan karena sarat doa sakral','Dicuci dengan air bersih','Disetrika dengan api sedang','Dikenakan oleh orang tua','A','Kain sarat doa luhur harus dihormati dan dirawat dengan penuh adab.'),
(12,'Apakah makna kata ''Mukti'' pada nama motif Batik Sidomukti?','Makmur, sejahtera, berkecukupan rezeki, dan bahagia lahir batin','Kuat dalam berperang','Cepat dalam berlari','Pandai berdagang di laut','A','Mukti bermakna hidup makmur, sejahtera, tenteram, dan mulia lahir batin.'),
(12,'Apakah arti kata ''Sido'' dalam bahasa Jawa?','Menjadi, terlaksana, atau berkelanjutan','Berhenti atau selesai','Hilang atau lenyap','Terpecah menjadi dua','A','Sido bermakna menjadi, terlaksana, atau terus berkesinambungan.'),
(12,'Kain Batik Sidomukti merupakan busana pengantin paling utama dalam tradisi pernikahan adat...','Pernikahan adat Jawa (Keraton Surakarta dan Yogyakarta)','Pernikahan adat Minangkabau','Pernikahan adat Betawi Palang Pintu','Pernikahan adat Bali Madya','A','Sidomukti adalah busana panggih pengantin Jawa paling agung dan tersohor.'),
(12,'Pesan filosofis apakah yang terkandung dalam pemakaian kain Sidomukti oleh kedua mempelai?','Doa agar rumah tangga baru senantiasa dilimpahi kemakmuran, kedamaian, dan rezeki halal','Harapan agar segera menjadi penguasa wilayah','Cita-cita menaklukkan kerajaan tetangga','Peringatan akan bahaya musim kemarau','A','Sidomukti menyimbolkan doa kemakmuran, kerukunan, dan kebahagiaan rumah tangga.'),
(12,'Istilah mengenakan kain batik bermotif serasi dan senada antara suami dan istri dinamakan...','Sarimbit','Wiron','Bebet','Kemben','A','Sarimbit berarti pasangan busana batik yang serasi antara pria dan wanita.'),
(12,'Ornamen takhta singgasana pada Sidomukti melambangkan...','Kedudukan terhormat, derajat mulia, dan ketenteraman rumah tangga laksana istana','Kekuasaan diktator seorang raja','Benteng perlindungan dari serangan panah','Gudang penyimpanan emas batangan','A','Singgasana melambangkan ketenteraman dan kehormatan mahligai rumah tangga.'),
(12,'Ornamen sepasang kupu-kupu yang menghiasi Sidomukti melambangkan...','Cinta kasih yang tulus, kesetiaan pasangan, dan keindahan budi pekerti','Pertanda datangnya musim hujan lebat','Hama tanaman padi sawah','Ketakutan pada angin malam','A','Kupu-kupu menyimbolkan metamorfosis cinta yang setia dan membahagiakan.'),
(12,'Latar kosong di antara bidang motif Sidomukti biasanya dipenuhi oleh isen...','Ukel canting yang sangat rapat (isen ukel latar)','Garis lurus tebal','Lumpur tanah liat','Warna putih polos tanpa malam','A','Isen ukel yang rapat melambangkan rezeki yang melimpah dan tidak pernah terputus.'),
(12,'Warna klasik apakah yang menjadi ciri khas keagungan kain Sidomukti?','Cokelat sogan keemasan, hitam malam, dan dasar gading','Merah terang darah ayam','Biru muda pastel pesisir','Hijau toska neon','A','Sogan cokelat keemasan khas keraton memberikan wibawa luhur bagi pengantin.'),
(12,'Bahan pewarna kuning oker keemasan pada soga keraton diperoleh dari rebusan kayu...','Kayu Tegeran (Cudrania javanensis)','Kulit Buah Manggis','Akar Alang-Alang','Daun Sirih','A','Kayu tegeran menghasilkan rona kuning keemasan alami pada formula soga.'),
(12,'Bentuk pola geometris yang membingkai ragam hias Sidomukti adalah...','Belah ketupat (wajik) yang teratur','Segitiga tajam','Lingkaran konsentris','Garis zigzag diagonal','A','Pola wajik geometris simetris membingkai ornamen sakral Sidomukti.'),
(12,'Ornamen pohon hayat (Kalpataru) pada Sidomukti menyiratkan doa...','Keberkahan umur panjang, kesuburan anak keturunan, dan rezeki melimpah','Kekuatan memanjat pohon rimba','Kemampuan menanam padi ketan','Keinginan menguasai hutan belantara','A','Pohon hayat melambangkan anugerah kehidupan, kesuburan, dan rezeki yang berakar kuat.'),
(12,'Ornamen sayap burung garuda (Lar) pada Sidomukti memiliki makna simbolik...','Perlindungan ilahi dan keteguhan iman menghadapi cobaan hidup','Keinginan terbang ke negeri seberang','Simbol kesedihan duka cita','Tanda kemarahan ksatria','A','Lar garuda melambangkan perlindungan agung dan ketinggian cita-cita moral.'),
(12,'Bagaimanakah teknik melipat bagian depan kain batik jarik pengantin adat Jawa?','Dilipat secara wiron rapi berjumlah ganjil di bagian depan','Dipotong segitiga di bagian samping','Dibiarkan menjuntai kusut ke lantai','Diikat dengan tali rafia','A','Kain jarik di-wiron secara teratur dan anggun di bagian depan busana.'),
(12,'Mengapa kain Sidomukti tulis halus bernilai sangat tinggi bagi masyarakat Jawa?','Karena menjadi pusaka warisan keluarga yang sarat dengan doa-doa restu sakral','Karena menggunakan benang kawat baja','Karena dibuat menggunakan mesin pabrik otomatis','Karena hanya boleh dicuci setahun sekali','A','Kain batik pengantin merupakan pusaka keluarga berharga yang dirawat turun-temurun.'),
(12,'Tahap mencuci kain batik pengantin agar lilin malam hilang seluruhnya disebut...','Nglorod','Nyorek','Njaplak','Ngempol','A','Nglorod adalah perebusan akhir untuk melarutkan seluruh lapisan lilin malam.'),
(12,'Batik Sidomukti termasuk dalam rumpun besar gaya...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Modern Kontemporer','A','Sidomukti merupakan puncak estetika batik keraton Vorstenlanden.'),
(12,'Apakah arti filosofis dari perkawinan dalam adat tradisi Jawa yang disiratkan kain Sidomukti?','Penyatuan dua keluarga besar menuju kehidupan mulia, rukun, dan berbakti kepada masyarakat','Pesta pora kemewahan semata','Ajang unjuk kekuatan antar bangsawan','Perjanjian perdagangan antar pulau','A','Pernikahan adalah ikatan suci membangun rumah tangga yang mulia dan bermanfaat.'),
(12,'Bagian kain mori primissima katun yang rapat sangat dibutuhkan untuk Sidomukti karena...','Mampu menampung ribuan goresan ukel latar halus tanpa merembes bocor','Supaya kain terasa panas saat dipakai','Agar kain tahan terhadap goresan pisau','Karena kainnya sangat berat seperti karpet','A','Kerapatan benang primissima menjamin kehalusan detail isen ukel latar.'),
(12,'Perajin batik yang menorehkan cairan lilin malam pada kain mori menggunakan...','Canting tulis dari tembaga bergagang bambu','Kuas lukis cat minyak','Pena besi tinta celup','Spons busa basah','A','Canting tembaga bergagang bambu adalah alat tradisional pembatikan tulis.'),
(12,'Apakah fungsi air buah lerak dalam perawatan kain batik Sidomukti pengantin?','Membersihkan kain tanpa melunturkan warna soga keemasan','Memutihkan kain mori','Menghilangkan serat benang','Membuat kain kaku seperti triplek','A','Lerak merawat keaslian pigmen soga alam agar tetap cemerlang selama puluhan tahun.'),
(13,'Apakah arti kata ''Mulyo'' pada penamaan motif Batik Sidomulyo?','Mulia, terhormat, disegani karena kebajikannya, dan bahagia','Kaya raya harta benda semata','Kuat dalam pertarungan fisik','Cepat dalam menyelesaikan pekerjaan','A','Mulyo bermakna hidup mulia, terhormat, dan bahagia lahir batin.'),
(13,'Apakah arti kata ''Sido'' dalam bahasa Jawa yang menjadi awalan nama motif ini?','Menjadi, terlaksana, atau terus berkesinambungan','Berhenti atau selesai di tengah jalan','Hilang atau lenyap tanpa bekas','Terpisah satu sama lain','A','Sido bermakna menjadi, terlaksana, atau terwujud secara berkesinambungan.'),
(13,'Nilai filosofis apakah yang menjadi inti ajaran moral Batik Sidomulyo?','Kemuliaan sejati manusia lahir dari budi pekerti luhur dan kedermawanan menolong sesama','Menuntut penghormatan dari orang lain','Menimbun kekayaan materi tanpa berbagi','Mengasingkan diri dari pergaulan sosial','A','Sidomulyo mengajarkan bahwa kemuliaan sejati bersumber dari amal kebajikan.'),
(13,'Empat ornamen utama apakah yang tersusun berselang-seling di dalam kisi-kisi wajik Sidomulyo?','Pohon hayat, sayap garuda (lar), bangunan pura/joglo, dan kupu-kupu','Naga, harimau, gajah, dan banteng','Matahari, bulan, bintang, dan awan petir','Keris, tameng, pedang, dan tombak','A','Empat ornamen kosmik: pohon hayat, sayap garuda, bangunan pura, dan kupu-kupu.'),
(13,'Ornamen bangunan pura atau rumah joglo pada motif Sidomulyo melambangkan...','Ketenteraman, perlindungan, dan keharmonisan istana mahligai rumah tangga','Benteng pertahanan dari serangan panah musuh','Gudang penyimpanan hasil panen padi','Tempat persinggahan kafilah dagang','A','Bangunan suci melambangkan keharmonisan dan ketenteraman rumah tangga.'),
(13,'Ornamen pohon hayat (pohon kehidupan) pada motif Sidomulyo menyimbolkan...','Anugerah kehidupan yang berakar kuat dan rezeki yang terus bertumbuh','Pohon hutan yang harus ditebang','Rintangan dalam perjalanan melaut','Tanda datangnya musim kemarau','A','Pohon hayat melambangkan poros kehidupan dan berkah rezeki yang tak pernah putus.'),
(13,'Ornamen sepasang sayap burung garuda (lar) melambangkan sifat ksatria berupa...','Keteguhan iman, keberanian membela kebenaran, dan perlindungan agung','Keinginan menguasai angkasa raya','Simbol kesedihan masa lalu','Tanda kemarahan penguasa','A','Lar garuda melambangkan perlindungan ilahi dan keteguhan menegakkan kebenaran.'),
(13,'Ornamen kupu-kupu pada motif Sidomulyo menyiratkan pesan moral tentang...','Metamorfosis budi pekerti manusia menuju pribadi yang indah dan bermanfaat','Hewan perusak tanaman bunga','Tanda datangnya musim hujan','Ketidaksabaran mencari nafkah','A','Kupu-kupu adalah simbol metamorfosis penyempurnaan akhlak manusia.'),
(13,'Dalam upacara adat daur hidup manusia Jawa, kain Sidomulyo lazim dikenakan pada saat...','Upacara Tingkeban (Mitoni tujuh bulanan kehamilan) dan Siraman pengantin','Perayaan panen kopi di ladang','Pertunjukan sabung ayam tradisional','Lomba memancing ikan di muara','A','Sidomulyo dikenakan saat prosesi siraman dan mitoni mendoakan kemuliaan sang anak.'),
(13,'Warna klasik apakah yang mendominasi keagungan kain Batik Sidomulyo keraton?','Cokelat sogan matang, hitam malam, dan dasar putih gading','Merah menyala darah ayam pesisir','Biru toska terang dan kuning neon','Merah muda pastel pucat','A','Palet warna sogan klasik memancarkan aura keteduhan jiwa dan kemuliaan tradisi.'),
(13,'Pohon apakah yang kulit batangnya dimanfaatkan untuk memberi zat warna cokelat soga alami?','Pohon Soga Jambal (Peltoforumpterocarpum)','Pohon Kelapa Sawit','Pohon Jati Belanda','Pohon Pinus Hutan','A','Kulit soga jambal merupakan bahan utama pewarnaan cokelat alami batik klasik.'),
(13,'Bentuk geometris apakah yang membingkai keempat elemen ornamen Sidomulyo?','Belah ketupat (wajik) yang tertata rapi simetris','Segitiga runcing berundak','Lingkaran konsentris bertumpuk','Garis lurus memanjang tanpa batas','A','Kisi-kisi belah ketupat wajik membingkai setiap ornamen dalam harmoni yang seimbang.'),
(13,'Isen titik canting mikro berjumlah tujuh yang kerap menghiasi ornamen disebut...','Cecek Pitu','Sawut lereng','Mlinjon wajik','Ukel latar','A','Cecek pitu melambangkan permohonan ''pitulungan'' (pertolongan dan keselamatan ilahi).'),
(13,'Kain mori bermutu paling tinggi dengan anyaman benang rapat halus dinamakan...','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Parasut Tahan Angin','A','Mori Primissima adalah jenis katun nomor satu terbaik untuk membatik tulis halus.'),
(13,'Alat canting berbahan tembaga bergagang bambu berfungsi untuk...','Menorehkan cairan lilin malam panas secara presisi ke atas mori','Memotong tepi mori yang berlebih','Mengaduk zat pewarna di ember','Menghaluskan serat kain mori','A','Canting tembaga adalah alat pena lilin utama dalam seni membatik tulis.'),
(13,'Tahap menutupi bidang gambar ornamen dengan lilin malam tebal dinamakan...','Nembok','Nglorod','Nyorek','Njaplak','A','Nembok adalah menutup bidang luas dengan malam agar tidak terkena warna celup.'),
(13,'Proses meluruhkan lapisan lilin malam dari kain menggunakan air mendidih dinamakan...','Nglorod','Medel','Nyungging','Ngasah','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(13,'Doa kemuliaan yang dipanjatkan bagi pemakai kain Sidomulyo adalah...','Semoga senantiasa dilimpahi keluhuran akhlak, dijauhkan dari kehinaan, dan hidup tenteram','Semoga ditakuti oleh seluruh penduduk negeri','Semoga menjadi saudagar paling kikir','Semoga tidak memiliki tanggung jawab keluarga','A','Sidomulyo membawa doa agar pemakainya menjadi insan mulia yang dicintai sesama.'),
(13,'Batik Sidomulyo termasuk dalam rumpun gaya batik...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Modern Kontemporer','A','Sidomulyo merupakan mahakarya batik keraton Surakarta dan Yogyakarta.'),
(13,'Mengapa pembuatan Batik Sidomulyo tulis membutuhkan ketelitian yang sangat tinggi?','Karena harus menjaga keseimbangan proporsi empat ornamen berbeda di setiap kisi wajik','Karena harus dibatik di bawah sinar rembulan malam','Karena menggunakan lilin malam beku','Karena tidak boleh melihat pola gambar','A','Keseimbangan empat ornamen di kisi wajik menuntut kestabilan dan kemahiran tinggi pembatik.'),
(13,'Sabun pembersih alami tradisional yang terbuat dari buah lerak berfungsi untuk...','Mencuci kain batik secara lembut tanpa merusak serat kain dan warna sogan alami','Memudarkan warna kain dengan cepat','Menghilangkan bau harum kain','Mengeraskan serat kain mori','A','Lerak adalah pembersih alami ber-pH seimbang yang menjaga keawetan warna batik.'),
(14,'Dari manakah daerah asal berkembangnya motif Batik Singa Barong?','Cirebon, Jawa Barat','Pekalongan, Jawa Tengah','Surakarta Hadiningrat','DKI Jakarta','A','Singa Barong merupakan mahakarya legendaris Keraton Kasepuhan Cirebon.'),
(14,'Benda pusaka keraton apakah yang mengilhami penciptaan motif Batik Singa Barong?','Kereta Kencana Singa Barong karya Panembahan Losari (tahun 1549)','Mahkota emas raja Singasari','Keris pusaka Kyai Sengkelat','Gamelan sekaten perunggu','A','Terinspirasi langsung dari Kereta Kencana Singa Barong keraton Cirebon.'),
(14,'Unsur budaya Tionghoa pada figur Singa Barong diwakili oleh bagian tubuh berwujud...','Kepala naga bertanduk dan bersisik','Sayap burung buroq','Belalai gajah','Kaki singa perkasa','A','Kepala naga melambangkan kearifan dan persahabatan dengan budaya Tionghoa.'),
(14,'Unsur budaya India / Hindu pada figur Singa Barong diwakili oleh bagian tubuh berwujud...','Belalai gajah yang menggenggam senjata trisula','Sayap burung merak','Ekor kuda sembrani','Cakar burung rajawali','A','Gajah berbelalai memegang trisula melambangkan kearifan budaya India/Hindu.'),
(14,'Unsur budaya Islam / Timur Tengah pada figur Singa Barong diwakili oleh...','Sepasang sayap burung garuda / buroq yang mengembang megah','Tanduk rusa emas','Sisik ikan mas kancra','Mata elang malam','A','Sayap buroq melambangkan kecepatan spiritual dan peradaban Islam.'),
(14,'Unsur budaya bumiputera Jawa pada figur Singa Barong diwakili oleh bagian tubuh berwujud...','Badan singa yang perkasa dan berwibawa','Belalai gajah panjang','Tanduk naga kembar','Paruh burung enggang','A','Badan singa melambangkan keberanian ksatria dan kedaulatan tanah Jawa.'),
(14,'Senjata apakah yang digenggam pada ujung belalai gajah Singa Barong?','Senjata Trisula (tombak bermata tiga)','Keris berlekuk sembilan','Pedang samurai panjang','Bilah mandau Dayak','A','Trisula melambangkan ketegasan menegakkan keadilan dan tiga pilar kebenaran.'),
(14,'Pesan filosofis agung apakah yang disampaikan melalui gabungan empat satwa pada Singa Barong?','Toleransi, persaudaraan lintas budaya dan agama, serta persatuan bangsa','Peringatan akan bahaya peperangan saudara','Kekuatan menaklukkan samudra luas','Rasa takut pada makhluk gaib hutan','A','Singa Barong adalah simbol toleransi dan harmonisasi peradaban dunia di Cirebon.'),
(14,'Ornamen bebatuan karang khas Cirebon yang kerap mendampingi figur Singa Barong dinamakan...','Ornamen Wadasan','Ornamen Mlinjon','Ornamen Meru','Ornamen Tumpal','A','Wadasan adalah ornamen batu karang tebing simbol keteguhan pondasi iman.'),
(14,'Pada masa lampau di Cirebon, motif Singa Barong hanya boleh dikenakan oleh...','Sultan dan keluarga bangsawan Keraton Cirebon (Batik Larangan Istana)','Para saudagar perahu nelayan','Prajurit garda perbatasan','Para perajin tembikar pasar','A','Dahulu Singa Barong merupakan batik larangan sakral pembesar keraton Cirebon.'),
(14,'Upacara adat tahunan di Keraton Cirebon tempat kereta kencana Singa Barong disucikan adalah...','Upacara Panjang Jimat (Peringatan Maulid Nabi)','Upacara Labuhan Laut Kidul','Upacara Sekaten Solo','Upacara Kasada Tengger','A','Panjang Jimat adalah ritual sakral pembersihan pusaka keraton Cirebon.'),
(14,'Palet warna klasik apakah yang mendominasi Batik Singa Barong keraton?','Cokelat sogan pesisir, hitam malam pekat, dan dasar gading mori','Warna merah muda pastel dan ungu','Kuning terang menyala neon','Hijau toska mencolok','A','Sogan cokelat pesisir dan hitam pekat memberikan wibawa agung pada figur satwa.'),
(14,'Desa sentra industri batik di Cirebon yang terkenal memproduksi Singa Barong halus adalah...','Desa Trusmi (Kecamatan Plered)','Desa Kauman Solo','Desa Laweyan','Desa Krapyak Pekalongan','A','Desa Trusmi Cirebon merupakan sentra legendaris perajin batik Cirebonan.'),
(14,'Alat canting cucuk kecil digunakan oleh pembatik Singa Barong khusus untuk...','Menorehkan sisik naga mikro, bulu surai singa, dan mata trisula','Memotong kain mori yang kusut','Mencelup kain ke dalam bejana pewarna','Mengikis lilin malam yang beku','A','Canting cucuk mikro dipakai untuk menggambar rincian anatomis satwa mitologi.'),
(14,'Bahan baku lilin malam batik Cirebon diramu dari campuran bahan alami...','Gondorukem, getah damar mata kucing, dan lilin lebah (malam tawon)','Semen putih dan minyak tanah','Tepung kanji dan getah pisang','Abu gosok dan cairan cuka','A','Gondorukem, damar, dan lilin lebah memberikan kelenturan optimal saat dicanting.'),
(14,'Apakah fungsi ornamen awan Mega Mendung yang kerap mengitari figur Singa Barong?','Memberi suasana sejuk, keteduhan batin, dan keagungan kosmos kahyangan','Menunjukkan tanda bahaya badai topan','Menutupi kesalahan gambar pembatik','Memperberat bobot kain jarik','A','Awan mendung melambangkan keteduhan dan rahmat semesta pelindung bumi.'),
(14,'Batik Singa Barong membuktikan bahwa Kesultanan Cirebon pada abad ke-16 adalah...','Kerajaan maritim yang sangat maju, toleran, dan kosmopolit merangkul bangsa-bangsa dunia','Kerajaan yang terisolasi dari peradaban luar','Kerajaan yang menolak pedagang asing','Kerajaan yang hanya mengandalkan peperangan','A','Cirebon adalah bandar maritim internasional yang menjunjung tinggi toleransi bangsa.'),
(14,'Bagian tubuh singa pada motif Singa Barong digambarkan dalam posisi...','Melangkah gagah ke depan dengan cakar kokoh mencengkeram bumi','Tidur terlentang di dalam gua','Meringkuk ketakutan di sudut kain','Tenggelam di dasar samudra','A','Singa Barong melangkah gagah ke depan melambangkan kewibawaan melangkah maju.'),
(14,'Kain mori sutra halus sangat cocok untuk membatik Singa Barong kebesaran karena...','Mampu memancarkan kilau mewah dan goresan canting malam tembus sempurna','Kainnya sangat kaku seperti kayu','Harganya paling murah di pasaran','Mudah menyerap lumpur sawah','A','Mori sutra halus memancarkan keagungan visual motif kebesaran keraton.'),
(14,'Tahap akhir meluruhkan lilin malam dari kain batik dengan air panas mendidih dinamakan...','Nglorod','Nyorek','Njaplak','Ngempol','A','Nglorod adalah perebusan akhir untuk melarutkan seluruh lapisan lilin malam.'),
(14,'Pesan toleransi pada motif Singa Barong sangat relevan dengan semboyan bangsa Indonesia, yaitu...','Bhinneka Tunggal Ika (Berbeda-beda tetapi tetap satu jua)','Tut Wuri Handayani','Ing Ngarsa Sung Tuladha','Gemah Ripah Loh Jinawi','A','Singa Barong adalah manifestasi visual luhur dari semangat Bhinneka Tunggal Ika.'),
(15,'Apakah arti kata ''Sri'' pada penamaan motif Batik Srikaton?','Cahaya kemilau, keagungan, keindahan, dan kemakmuran','Batu karang laut dalam','Angin topan yang kencang','Senjata perang bermata tajam','A','Sri bermakna cahaya kemilau keagungan, keindahan, dan dewi pembawa kemakmuran.'),
(15,'Apakah arti kata ''Katon'' dalam bahasa Jawa pada motif Srikaton?','Tampak jelas, bercahaya, berseri-seri, dan terlihat wibawanya','Tersembunyi di dalam tanah','Hilang tertelan kegelapan','Terlupakan oleh zaman','A','Katon bermakna tampak jelas, berseri-seri, dan memancarkan wibawa pesona.'),
(15,'Pesan filosofis apakah yang terkandung dalam pemakaian Batik Srikaton?','Harapan agar pemakainya tampak berseri-seri, berwibawa, dan dicintai karena kebaikan budinya','Mengejar pujian dan sanjungan semu','Menakut-nakuti orang yang lebih lemah','Menonjolkan perhiasan emas yang berlebihan','A','Srikaton membawa doa agar pemakainya memancarkan pesona kebajikan yang berseri.'),
(15,'Dari manakah lingkungan tradisi asal penciptaan Batik Srikaton?','Keraton Kasunanan Surakarta Hadiningrat (Solo)','Pesisir Pelabuhan Cirebon','Kawasan Pegunungan Dieng','Pesisir Pantai Madura','A','Srikaton merupakan mahakarya klasik Keraton Kasunanan Surakarta Hadiningrat.'),
(15,'Pada masa lampau, motif Srikaton diciptakan secara khusus untuk busana kalangan...','Para putri dan permaisuri keraton Surakarta dalam upacara agung istana','Para prajurit penjaga benteng luar','Para kusir kereta kuda istana','Para petani pembajak sawah','A','Srikaton dirancang khusus menghias busana kebesaran putri dan keluarga bangsawan.'),
(15,'Ornamen flora utama apakah yang mendominasi komposisi Batik Srikaton?','Gubahan mahkota kuncup bunga teratai anggun yang merekah berseri','Batang kaktus berduri tajam','Daun keladi hutan liar','Pohon karet getah','A','Mahkota bunga yang merekah indah menjadi titik fokus visual keanggunan Srikaton.'),
(15,'Ornamen pendamping apakah yang menyertai mahkota bunga untuk melambangkan kewibawaan?','Sayap garuda mini (lar) dan ornamen lidah api kebajikan','Tanduk banteng liar','Bilah keris berkarat','Taring babi hutan','A','Sayap garuda dan lidah api melambangkan wibawa moral dan semangat kebajikan hidup.'),
(15,'Warna klasik apakah yang menjadi ciri khas keanggunan motif Srikaton Solo?','Cokelat sogan hangat kekuningan, hitam malam, dan dasar gading mori','Merah muda cerah dan hijau toska','Ungu terong dan abu-abu gelap','Kuning terang neon','A','Sogan hangat khas Solo memancarkan rona teduh, anggun, dan berkarakter ningrat.'),
(15,'Bahan pewarna kuning oker alami pada formula soga keraton diperoleh dari kayu...','Kayu Tegeran (Cudrania javanensis)','Kulit Buah Manggis','Akar Alang-Alang','Daun Sirih','A','Kayu tegeran menghasilkan rona kuning keemasan alami pada soga keraton.'),
(15,'Kapan momentum adat yang paling tepat untuk mengenakan kain Batik Srikaton?','Upacara pisowanan keraton, resepsi pernikahan adat, dan penyambutan tamu agung','Saat berburu hewan di hutan','Saat menaiki perahu nelayan','Saat tidur di kamar peraduan','A','Srikaton dikenakan pada perhelatan resmi istana dan resepsi pernikahan adat agung.'),
(15,'Bagaimanakah susunan tata letak ornamen pada sehelai kain Srikaton?','Tertata rapi dalam kisi-kisi simetris yang tenang, anggun, dan seimbang','Miring berlereng tajam 45 derajat tanpa bunga','Berantakan secara acak dan bebas','Hanya berupa satu garis lurus tebal','A','Keteraturan simetris yang tenang mencerminkan kepribadian wanita keraton yang santun.'),
(15,'Apakah fungsi isen sawut halus yang melengkung pada kelopak bunga Srikaton?','Memberikan kesan volume tiga dimensi dan kelopak bunga yang semerbak merekah','Menutup kain yang robek','Menambah berat timbangan kain','Menghapus coretan tinta','A','Sawut berupa garis-garis lembut melengkung pemberi tekstur dan keindahan kelopak.'),
(15,'Kain mori bermutu terbaik yang serat benangnya paling rapat untuk membatik Srikaton adalah...','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Parasut Sintetis','A','Mori Primissima adalah mori bermutu tertinggi untuk membatik tulis halus.'),
(15,'Alat canting dengan cucuk (corong tembaga) paling halus digunakan khusus untuk...','Menorehkan isen cecek mikro dan sawut kelopak bunga','Memblok bidang latar kain yang luas','Mencelup kain ke dalam bejana warna','Mengikis lilin malam yang sudah dingin','A','Canting cucuk mikro digunakan untuk membuat titik-titik ornamen halus.'),
(15,'Apakah makna filosofis dari wajah yang ''katon'' (tampak berseri) dalam ajaran Jawa?','Pancaran nurani yang bersih, jujur, ramah, dan berakhlak mulia','Wajah yang dirias dengan bedak paling tebal','Wajah yang selalu menunjukkan kemarahan','Wajah yang ditutupi oleh topeng kayu','A','Kecantikan sejati terpancar dari ketulusan hati nurani dan budi pekerti santun.'),
(15,'Proses mencuci kain batik halus menggunakan sabun buah lerak bertujuan untuk...','Merawat keawetan serat kain mori dan menjaga kecerlangan warna soga alami','Membuat warna kain cepat pudar','Menghilangkan aroma lilin malam','Mengeraskan kain mori','A','Lerak adalah pembersih alami ber-pH seimbang yang menjaga keawetan warna batik.'),
(15,'Batik Srikaton digolongkan ke dalam rumpun besar batik...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Baduy Kuno','A','Srikaton merupakan mahakarya klasik Keraton Kasunanan Surakarta.'),
(15,'Bahan baku lilin malam batik diramu dari campuran bahan alami berupa...','Gondorukem, damar mata kucing, dan lilin lebah (malam tawon)','Semen putih dan minyak goreng','Tepung tapioka dan getah karet','Pewarna tekstil dan air cuka','A','Lilin malam diramu dari gondorukem, damar mata kucing, dan lilin lebah.'),
(15,'Tahap melarutkan lilin malam dari kain dengan air panas mendidih dinamakan...','Nglorod','Nyorek','Njaplak','Ngempol','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(15,'Garis outline pola utama batik yang pertama kali digambar di atas kain dinamakan...','Garis Lowongan','Isen-isen','Tembokan','Lorodan','A','Garis lowongan adalah garis kontur utama yang membingkai ragam hias motif.'),
(15,'Dalam tata busana adat Jawa, kain jarik Srikaton yang dikenakan wanita dipadukan dengan...','Kebaya beludru hitam berhias sulaman emas atau kebaya kutubaru','Baju kaos oblong santai','Jaket parasut bertudung','Rompi jeans kasual','A','Kain jarik Srikaton berpadu anggun dengan kebaya beludru klasik keraton.'),
(16,'Apakah arti kata ''Tri'' pada penamaan motif Batik Tribusono?','Tiga','Satu','Lima','Tujuh','A','Tri berasal dari bahasa Sanskerta/Kawi yang bermakna tiga.'),
(16,'Apakah arti kata ''Busono'' atau ''Busana'' dalam tradisi kebudayaan Jawa?','Pakaian, perhiasan, atau tatanan etika yang menghiasi diri','Senjata pusaka berbilah tajam','Makanan pesta perayaan','Alat transportasi kereta kuda','A','Busono bermakna pakaian, perhiasan, atau tatanan etika yang memperindah manusia.'),
(16,'Apakah tiga dimensi busana batin yang menjadi ajaran moral utama Batik Tribusono?','Busana Raga (kesopanan), Busana Jiwa (kejujuran), dan Busana Budi (kebijaksanaan)','Baju tidur, baju pesta, dan baju perang','Kain katun, kain sutra, dan kain wol','Busana anak-anak, remaja, dan orang tua','A','Tiga busana batin: kesopanan raga, kebersihan jiwa, dan keluhuran budi pekerti.'),
(16,'Nilai filosofis apakah yang ditekankan oleh motif Tribusono bagi kehidupan bermasyarakat?','Keselarasan antara penampilan lahiriah yang santun dan kemurnian hati nurani','Menilai orang hanya dari pakaian mahalnya','Mengutamakan kemewahan di atas kejujuran','Menyombongkan asal usul keturunan','A','Tribusono mengajarkan keselarasan antara kesantunan lahiriah dan kemurnian batin.'),
(16,'Dari manakah lingkungan tradisi asal penciptaan Batik Tribusono?','Keraton Surakarta dan Kesultanan Yogyakarta','Pesisir Madura Timur','Pedalaman Suku Dayak','Kawasan Pelabuhan Batavia','A','Tribusono diciptakan dan dilestarikan di lingkungan keraton Surakarta dan Yogyakarta.'),
(16,'Berapakah gugusan ornamen utama yang membentuk komposisi pola Batik Tribusono?','Tiga gugusan ornamen utama','Sepuluh ornamen acak','Satu garis lurus tunggal','Lima puluh ornamen bebas','A','Tribusono membagi bidang kain ke dalam tiga gugusan ornamen pokok.'),
(16,'Ragam hias flora apakah yang kerap digubah dalam tiga gugusan Tribusono?','Flora berdaun tiga, sulur paku-pakuan, dan ornamen kuncup bunga','Pohon kelapa sawit','Batang kaktus gurun','Bunga bangkai raksasa','A','Flora berdaun tiga dan sulur paku menyimbolkan pertumbuhan kebajikan hidup.'),
(16,'Ornamen titik canting mikro berjumlah tiga yang sering menghiasi motif disebut...','Cecek Tiga (Cecek Telu)','Cecek Pitu','Mlinjon wajik','Lar garuda','A','Cecek telu melambangkan kesatuan tiga pilar etika: raga, jiwa, dan budi.'),
(16,'Warna klasik apakah yang mendominasi keagungan kain Batik Tribusono?','Cokelat sogan matang, hitam pekat, dan dasar gading mori','Merah terang darah ayam pesisir','Kuning neon dan jingga muda','Biru toska terang','A','Palet warna sogan agung khas keraton mendominasi keanggunan motif Tribusono.'),
(16,'Pohon apakah yang kulit batangnya menjadi bahan utama pewarna cokelat soga alami?','Pohon Soga Jambal (Peltoforumpterocarpum)','Pohon Jati Belanda','Pohon Randu Alas','Pohon Mangga Golek','A','Kulit soga jambal merupakan bahan utama pewarnaan cokelat alami batik klasik.'),
(16,'Kapan momentum adat yang tepat untuk mengenakan kain Batik Tribusono?','Pertemuan musyawarah tetua adat, pisowanan agung, dan upacara keluarga','Saat mencangkul tanah sawah','Saat berenang di sungai deras','Ketika beristirahat di malam hari','A','Tribusono dikenakan pada pertemuan resmi musyawarah dan upacara adat terhormat.'),
(16,'Bagaimanakah susunan tata letak ornamen pada sehelai kain Tribusono?','Tertata rapi dalam kisi-kisi simetris yang tenang dan seimbang','Miring berlereng tajam 45 derajat tanpa daun','Berantakan secara acak dan bebas','Membentuk lingkaran tunggal di tengah','A','Keteraturan simetris mencerminkan ketertiban tatanan moral manusia beradab.'),
(16,'Kain mori katun apakah yang memiliki anyaman paling rapat dan halus untuk membatik?','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Terpal Sintetis','A','Mori Primissima adalah mori bermutu tertinggi untuk membatik tulis halus.'),
(16,'Alat canting berbahan tembaga berfungsi untuk...','Menorehkan cairan lilin malam panas secara presisi ke atas mori','Memotong kain mori yang kusut','Mencelup kain ke dalam pewarna soga','Menghaluskan serat kain mori','A','Canting tembaga adalah alat pena lilin utama dalam seni membatik tulis.'),
(16,'Tahap menutupi bidang gambar ornamen dengan lilin malam tebal dinamakan...','Nembok','Nglorod','Nyorek','Njaplak','A','Nembok adalah menutup bidang luas dengan malam agar tidak terkena warna celup.'),
(16,'Proses meluruhkan lapisan lilin malam dari kain menggunakan air mendidih dinamakan...','Nglorod','Medel','Nyungging','Ngasah','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(16,'Mengapa pembuatan Batik Tribusono tulis membutuhkan kesabaran yang tinggi?','Karena harus menjaga keseimbangan tiga gugusan ornamen pada seluruh bentangan mori','Karena harus dibatik sambil bernyanyi','Karena menggunakan lilin malam beku','Karena tidak boleh melihat pola gambar','A','Keseimbangan tiga ornamen menuntut kestabilan tangan dan ketelitian tinggi pembatik.'),
(16,'Apakah fungsi isen sawut halus yang melengkung pada daun ornamen Tribusono?','Memberikan kesan volume tiga dimensi dan tekstur dedaunan yang lentur','Menutup kain yang robek','Menambah berat timbangan kain','Menghapus coretan pola','A','Sawut berupa garis-garis lembut melengkung pemberi tekstur dan bayangan daun.'),
(16,'Sabun pembersih alami tradisional yang terbuat dari buah lerak berfungsi untuk...','Mencuci kain batik secara lembut tanpa merusak warna soga alami','Membuat warna kain cepat pudar','Menghilangkan aroma lilin malam','Mengeraskan serat kain mori','A','Lerak adalah pembersih alami ber-pH seimbang yang menjaga keawetan warna batik.'),
(16,'Batik Tribusono termasuk dalam rumpun besar gaya...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Baduy Pesisir','A','Tribusono merupakan bagian dari mahakarya klasik keraton Jawa Vorstenlanden.'),
(16,'Bahan baku lilin malam batik diramu dari campuran bahan alami berupa...','Gondorukem, damar mata kucing, dan lilin lebah (malam tawon)','Semen putih dan minyak goreng','Tepung tapioka dan getah karet','Pewarna tekstil dan air cuka','A','Lilin malam diramu dari gondorukem, damar mata kucing, dan lilin lebah.'),
(17,'Dari kota pesisir manakah motif Batik Tujuh Rupa berasal?','Pekalongan, Jawa Tengah','Surakarta Hadiningrat','Cirebon Jawa Barat','DKI Jakarta','A','Tujuh Rupa adalah ikon mahakarya pesisir Kota Pekalongan.'),
(17,'Apakah arti kata ''Tujuh'' (pitu) dalam kearifan filosofi Jawa pada motif ini?','Pitulungan (pertolongan dan keselamatan dari Tuhan)','Tujuh hari dalam seminggu','Tujuh prajurit berkuda istana','Tujuh buah gunung berapi','A','Kata pitu bermakna pitulungan (pertolongan dan anugerah ilahi).'),
(17,'Ciri khas visual yang paling menonjol pada Batik Tujuh Rupa dibandingkan batik keraton adalah...','Warnanya sangat beragam dan meriah (polikromatik) dengan motif flora-fauna naturalis','Hanya menggunakan warna cokelat gelap','Bermotif garis lurus diagonal kaku','Hanya bergambar senjata perang','A','Batik Tujuh Rupa identik dengan aneka warna cerah meriah dan ornamen alam.'),
(17,'Akulturasi budaya apakah yang melahirkan keindahan Batik Tujuh Rupa di Pekalongan?','Perpaduan budaya bumiputera Jawa, Tionghoa, dan Eropa di pesisir utara','Budaya suku Maya dan Aztec','Budaya Yunani kuno dan Romawi','Budaya suku Aborigin Australia','A','Tujuh Rupa lahir dari perjumpaan kultural Jawa pesisir, Tionghoa, dan Eropa.'),
(17,'Flora apakah yang kerap mendominasi ragam hias pada Batik Tujuh Rupa?','Bunga teratai, mawar, aster, dahlia, dan krisan yang mekar indah','Batang kaktus berduri tajam','Pohon pinus pegunungan','Rumput ilalang kering','A','Ragam flora tropis yang mekar indah menjadi elemen pokok motif ini.'),
(17,'Fauna apakah yang sering digambarkan melayang di sekitar bunga-bunga Tujuh Rupa?','Kupu-kupu, burung merpati, merak, dan capung lincah','Gajah afrika dan singa padang pasir','Ikan paus samudra dalam','Ular kobra melingkar','A','Kupu-kupu dan burung melambangkan kebebasan dan keceriaan hidup.'),
(17,'Teknik mewarnai bagian motif tertentu menggunakan kuas bambu kecil disebut...','Teknik colet (coletan)','Teknik celup rintang','Teknik tenun ikat','Teknik bordir sulam','A','Teknik colet memungkinkan puluhan warna cerah tertoreh pada satu helai kain.'),
(17,'Pesan moral apakah yang diajarkan melalui keanekaragaman warna pada Batik Tujuh Rupa?','Hidup harus disikapi dengan optimisme, keceriaan, dan keyakinan akan datangnya pertolongan Tuhan','Menyerah menghadapi kesulitan hidup','Memaksakan semua orang agar memiliki selera yang sama','Menghindari perjumpaan dengan orang asing','A','Keceriaan warna menyiratkan optimisme dan keyakinan akan berkah pertolongan Tuhan.'),
(17,'Batik Tujuh Rupa sangat digemari kaum perempuan pesisir sebagai busana...','Kain sarung kebaya pesta (sarung encim) dan selendang anggun','Baju zirah perang besi','Pakaian tidur tebal','Rompi kerja tambang batu','A','Kain sarung Tujuh Rupa berpadu anggun dengan kebaya encim pesisir.'),
(17,'Pewarna sintetis yang mulai digunakan sejak awal abad ke-20 untuk warna cerah Pekalongan adalah...','Pewarna Naphtol dan Indigosol','Cat minyak lukis kanvas','Tinta printer komputer','Serbuk arang kayu bakar','A','Naphtol dan Indigosol menghadirkan warna-warna cerah tahan luntur di Pekalongan.'),
(17,'Bagian kepala kain sarung Tujuh Rupa biasanya dihiasi ornamen tumpal berpola...','Pucuk rebung segitiga yang melambangkan pertumbuhan budi luhur','Lingkaran roda berputar','Garis zigzag patah','Huruf aksara kuno','A','Tumpal pucuk rebung menghiasi kepala sarung sebagai penyeimbang kosmos.'),
(17,'Apakah fungsi isen cecek byur pada latar kain Batik Tujuh Rupa?','Memenuhi ruang kosong mori dengan titik-titik lembut memberi tekstur elegan','Menghilangkan warna kain mori','Menambah ketebalan kain','Mempercepat pengeringan lilin','A','Cecek byur memberikan tekstur lembut yang anggun pada latar kain.'),
(17,'Kain mori primissima katun halus sangat digemari perajin Pekalongan karena...','Permukaannya rata dan rapat sehingga zat warna colet tidak meluber keluar garis','Harganya paling mahal di dunia','Kainnya sangat kaku seperti kayu','Tidak dapat dicuci air','A','Mori primissima memastikan garis lilin dan warna colet tertoreh presisi.'),
(17,'Batik Tujuh Rupa termasuk ke dalam rumpun besar gaya batik...','Batik Pesisiran (Batik Pekalongan)','Batik Keraton Klasik Vorstenlanden','Batik Pedalaman Kuno','Batik Monokromatis','A','Tujuh Rupa adalah puncak ekspresi keceriaan batik pesisir Pekalongan.'),
(17,'Tahap akhir melarutkan lilin malam dari kain batik dengan air panas mendidih dinamakan...','Nglorod','Nyorek','Njaplak','Ngempol','A','Nglorod adalah perebusan akhir untuk melarutkan seluruh lapisan lilin malam.'),
(17,'Alat canting dengan cucuk (corong tembaga) nomor satu digunakan oleh pembatik untuk...','Menorehkan garis kerangka kelopak bunga dan sayap kupu-kupu','Mencelup kain ke dalam ember warna','Mengaduk air mendidih kawah','Mengeringkan kain di jemuran','A','Canting klowong nomor satu digunakan untuk menggambar kontur garis pola.'),
(17,'Mengapa Batik Tujuh Rupa tidak memiliki aturan ''Batik Larangan'' seperti batik keraton?','Karena lahir di lingkungan masyarakat pesisir yang egaliter, bebas, dan terbuka','Karena harganya terlalu murah','Karena dilarang oleh pemerintah kolonial','Karena tidak ada yang berminat memakainya','A','Masyarakat pesisir Pekalongan menjunjung tinggi kebebasan berekspresi tanpa batasan kasta.'),
(17,'Burung merak yang anggun pada kain sarung Tujuh Rupa melambangkan...','Keindahan budi, kemuliaan derajat, dan perlindungan dari mara bahaya','Pertanda musim paceklik','Hewan pemakan bangkai','Tanda datangnya badai topan','A','Burung merak melambangkan keanggunan, pesona keindahan, dan kemakmuran.'),
(17,'Sabun pembersih alami terbaik untuk merawat keawetan warna-warni Batik Tujuh Rupa adalah...','Cairan buah lerak alami','Deterjen pemutih berklorin tinggi','Sabun cuci piring pekat','Cairan pembersih lantai','A','Buah lerak merawat serat kain dan pigmen warna colet agar tetap cemerlang.'),
(17,'Garis outline lilin malam pada Batik Tujuh Rupa ditarik dengan karakter...','Luwes, dinamis, lentur, dan mengalir bebas mencerminkan nafas laut','Kaku, patah-patah, dan terputus','Sangat tebal seperti balok kayu','Dihapus setelah diwarnai','A','Garis canting pesisir berkarakter luwes dan bebas mengekspresikan gerak alam.'),
(17,'Sentra perdagangan dan pasar batik terbesar di Pekalongan tempat bertemunya perajin adalah...','Pasar Grosir Setono','Pasar Klewer Solo','Pasar Beringharjo Yogyakarta','Pasar Tanah Abang Jakarta','A','Pasar Grosir Setono adalah sentra niaga batik legendaris di Kota Pekalongan.'),
(18,'Siapakah tokoh permaisuri keraton yang menciptakan motif Batik Truntum?','Kanjeng Ratu Kencana (Permaisuri Pakubuwono III)','Ratu Hemas Yogyakarta','Ratu Kalinyamat Jepara','Putri Ong Tien Nio Cirebon','A','Truntum digubah oleh Kanjeng Ratu Kencana, permaisuri Sri Susuhunan Pakubuwana III.'),
(18,'Dari manakah lingkungan keraton asal terciptanya motif Batik Truntum?','Keraton Kasunanan Surakarta Hadiningrat (Solo)','Keraton Kasepuhan Cirebon','Pura Mangkunegaran','Kesultanan Banten','A','Truntum lahir dari perenungan hening di Keraton Kasunanan Surakarta Hadiningrat.'),
(18,'Kata ''Truntum'' berasal dari kata dalam bahasa Jawa ''Taruntum'' yang berarti...','Bersemi atau tumbuh kembali','Tenggelam dalam samudra','Batu karang yang terjal','Awan mendung penyejuk','A','Taruntum bermakna tumbuh kembali atau bersemi mekar laksana bunga cinta kasih.'),
(18,'Pemandangan alam apakah yang mengilhami Kanjeng Ratu Kencana saat mencanting motif ini di malam hari?','Tebaran bintang-bintang di langit malam yang hening dan kuncup melati','Ombak laut selatan yang bergemuruh','Letusan gunung berapi yang menyala','Hutan belantara rimba','A','Sang Ratu terinspirasi oleh gemerlap bintang di langit malam yang hening menenteramkan.'),
(18,'Apakah nilai filosofis utama yang disiratkan oleh motif Batik Truntum?','Cinta kasih tulus tanpa pamrih yang senantiasa bersemi abadi sepanjang masa','Kemenangan mutlak atas musuh perang','Keinginan menguasai kekayaan duniawi','Rasa takut pada kegelapan malam','A','Truntum adalah simbol cinta kasih tulus, kesetiaan sejati, dan harapan yang selalu bersemi.'),
(18,'Pada upacara pernikahan adat Jawa, kain Batik Truntum wajib dikenakan oleh...','Orang tua kedua mempelai pengantin','Para penari pengiring pesta','Sopir kereta kuda pengantin','Anak-anak kecil pembawa cincin','A','Orang tua pengantin wajib mengenakan Truntum sebagai lambang doa restu dan panutan.'),
(18,'Kata ''Truntum'' bagi orang tua pengantin juga memiliki makna ''Tuntum'' atau ''Nuntun'' yang berarti...','Menuntun anak menantunya memasuki mahligai kehidupan berumah tangga','Membiarkan anak berjalan sendiri tanpa nasihat','Menuntut harta mahar yang tinggi','Menghentikan langkah anak menantu','A','Nuntun bermakna menuntun dan membimbing kedua mempelai menuju kebahagiaan sejati.'),
(18,'Ornamen dasar apakah yang membentuk motif Batik Truntum?','Kuntum bunga melati mikro menyerupai bintang bersegi banyak yang tertata seragam','Garis lereng miring diagonal 45 derajat','Lingkaran besar kolang-kaling','Figur naga bersisik cakar tajam','A','Truntum tersusun atas ribuan kuntum bunga melati mikro berbentuk bintang malam.'),
(18,'Bagaimanakah warna latar pakem pada sehelai kain Batik Truntum klasik?','Hitam pekat atau cokelat soga gelap tanpa corak latar tambahan','Putih bersih menyala tanpa warna lain','Merah terang darah ayam','Kuning terang neon','A','Latar hitam pekat menyimbolkan langit malam tempat kuntum bintang melati bersinar.'),
(18,'Warna kuntum bintang melati pada Truntum klasik biasanya berwarna...','Putih gading mori berpadu cokelat soga keemasan','Merah menyala darah ayam','Hijau toska mencolok','Ungu terong gelap','A','Bintang melati berwarna gading dan soga keemasan memancarkan kehangatan cinta.'),
(18,'Alat canting jenis apakah yang digunakan khusus untuk membuat bintik-bintik cecek Truntum?','Canting cecek mikro (cucuk sangat halus)','Canting tembok bermulut lebar','Canting gayor berlubang lima','Kuas lukis cat minyak','A','Canting cecek mikro digunakan untuk merinci kelopak bunga melati yang sangat kecil.'),
(18,'Kerapatan susunan kuntum bintang pada sehelai kain Truntum harus dibuat...','Seragam, konsisten, dan berjarak teratur di seluruh kain mori','Acak-acakan tanpa pola','Hanya berkumpul di empat sudut kain','Dibiarkan renggang dengan ruang kosong lebar','A','Kerapatan dan keteraturan bintang menuntut kesabaran serta ketelitian ekstra pembatik.'),
(18,'Bahan mori katun halus jenis apakah yang paling tepat untuk membatik Truntum?','Mori Primissima berkepadatan benang tinggi','Kain Blacu Kasar Berbulu','Kain Goni Serat Pohon','Kain Terpal Sintetis','A','Mori primissima memiliki tekstur rapat halus yang menjaga ketajaman titik cecek mikro.'),
(18,'Batik Truntum termasuk dalam rumpun kategori batik...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Baduy Pesisir','A','Truntum merupakan mahakarya agung Keraton Kasunanan Surakarta.'),
(18,'Kisah penciptaan Batik Truntum membuktikan bahwa seni membatik di masa lampau berfungsi sebagai...','Media kontemplasi batin, doa hening, dan penyembuhan luka jiwa','Pekerjaan kasar buruh pelabuhan','Hukuman bagi putri yang bersalah','Ajang perlombaan kecepatan mencanting','A','Membatik adalah laku spiritual menenangkan batin dan menyatukan doa dengan karya.'),
(18,'Bahan pewarna cokelat alami soga pada kain Truntum dihasilkan dari rebusan kulit...','Kulit pohon soga jambal, kayu tegeran, dan kulit pohon tingi','Kulit buah durian','Akar rumput ilalang','Daun pepaya pahit','A','Formula soga klasik keraton diramu dari soga jambal, tegeran, dan tingi.'),
(18,'Proses mencelup kain mori ke dalam zat pewarna hitam pekat tradisional menggunakan campuran...','Wedelan daun nila (Indigofera) yang ditumpuk dengan soga tua','Tinta spidol hitam','Lumpur got air payau','Minyak jelantah hitam','A','Latar hitam pekat dihasilkan dari tumpang tindih celupan nila tua dan soga jambal.'),
(18,'Tahap akhir melarutkan lilin malam dari kain batik dengan air panas mendidih dinamakan...','Nglorod','Nyorek','Njaplak','Ngempol','A','Nglorod adalah perebusan akhir untuk melarutkan seluruh lapisan lilin malam.'),
(18,'Mengapa orang tua pengantin yang mengenakan kain Truntum memancarkan aura keteduhan?','Karena motif bintang melambangkan doa restu tulus orang tua yang membimbing langkah anaknya','Karena kainnya sangat berat menekan tubuh','Karena kainnya diberi wewangian parfum impor','Karena harganya paling mahal di pasar','A','Truntum melambangkan keteduhan doa restu orang tua yang membimbing keluarga baru.'),
(18,'Apakah fungsi air buah lerak alami dalam merawat kain Batik Truntum warisan leluhur?','Menjaga kain tetap lembut dan warna hitam sogan tidak luntur atau kusam','Mengikis serat kain benang','Memutihkan latar kain yang hitam','Mengeraskan kain mori','A','Lerak merawat keaslian pigmen soga alam agar tetap cemerlang selama berabad-abad.'),
(18,'Dalam upacara adat siraman pengantin, kain Truntum yang dikenakan orang tua menyimbolkan...','Pembersihan lahir batin dan limpahan kasih sayang orang tua yang tak terhingga','Kewajiban pengantin membayar utang orang tua','Tanda berakhirnya hubungan kekeluargaan','Keinginan memiliki rumah mewah','A','Siraman dengan Truntum melambangkan penyucian lahir batin bermandikan kasih sayang orang tua.'),
(19,'Apakah arti kata ''Wahyu'' pada penamaan motif Batik Wahyu Tumurun?','Petunjuk, anugerah, atau berkah kemuliaan dari Tuhan Yang Maha Esa','Angin kencang badai','Senjata pusaka berbilah tajam','Perahu layar nelayan','A','Wahyu bermakna petunjuk, anugerah berkah, atau wahyu kemuliaan dari Tuhan.'),
(19,'Apakah arti kata ''Tumurun'' dalam bahasa Jawa pada motif ini?','Turun atau mengalir dari langit','Naik ke puncak gunung','Hilang tertelan bumi','Berhenti di tempat','A','Tumurun bermakna turun mengalir ke bumi menyapa manusia.'),
(19,'Pesan filosofis apakah yang menjadi inti ajaran moral Batik Wahyu Tumurun?','Kemuliaan tahta dan kebahagiaan hidup adalah anugerah Tuhan yang wajib dijaga dengan amanah dan keadilan','Kekuasaan harus direbut dengan menghalalkan segala cara','Menimbun kekayaan materi sebanyak mungkin','Menghindari tanggung jawab kepemimpinan','A','Wahyu Tumurun mengajarkan bahwa berkah ilahi harus diemban dengan amanah dan keadilan.'),
(19,'Ornamen sakral apakah yang menjadi ciri visual utama motif Wahyu Tumurun?','Mahkota terbang (mustika mahkota kerajaan) yang melayang turun','Topeng raksasa bertaring','Perahu lesung nelayan','Pohon kaktus berduri','A','Mustika mahkota terbang adalah ornamen sentral perlambang anugerah ilahi.'),
(19,'Ornamen pendamping apakah yang mengapit mahkota pada Wahyu Tumurun?','Sepasang sayap burung garuda (lar) dan sepasang burung merak berhadapan','Dua ekor naga laut','Dua ekor gajah sumatra','Dua bilah pedang silang','A','Sepasang sayap garuda dan burung merak melambangkan perlindungan dan keselarasan hidup.'),
(19,'Dari manakah lingkungan tradisi asal penciptaan Batik Wahyu Tumurun?','Keraton Surakarta dan Kesultanan Yogyakarta','Pesisir Pelabuhan Cirebon','Kawasan Pecinan Lasem','Pedalaman Suku Dayak','A','Wahyu Tumurun merupakan mahakarya agung keraton Surakarta dan Yogyakarta.'),
(19,'Kapan momentum upacara adat yang lazim menggunakan kain Wahyu Tumurun?','Upacara pernikahan adat (panggih) dan pelantikan jabatan resmi keraton','Saat berolahraga panahan','Saat melaut mencari ikan','Ketika mencangkul tanah sawah','A','Wahyu Tumurun dikenakan pada upacara pernikahan adat dan pelantikan jabatan kehormatan.'),
(19,'Doa restu apakah yang dipanjatkan saat pengantin mengenakan kain Wahyu Tumurun?','Semoga kedua mempelai dilimpahi petunjuk kebenaran, kemakmuran, dan kedudukan mulia yang berkah','Semoga segera memiliki banyak perhiasan emas','Semoga ditakuti oleh seluruh warga kampung','Semoga terhindar dari kewajiban berderma','A','Kain ini membawa doa turunnya berkah petunjuk ilahi dan keharmonisan rumah tangga.'),
(19,'Warna klasik apakah yang mendominasi keagungan kain Batik Wahyu Tumurun?','Cokelat sogan matang, hitam pekat, dan dasar gading mori','Merah muda cerah dan biru muda pastel','Kuning terang neon menyala','Hijau toska mencolok','A','Palet warna sogan keraton memancarkan wibawa kepemimpinan yang tenang dan matang.'),
(19,'Bahan pewarna cokelat alami soga berasal dari campuran kulit pohon...','Soga jambal, kayu tegeran, dan kulit pohon tingi','Kulit buah durian','Akar rumput ilalang','Daun sirih kuning','A','Soga jambal, tegeran, dan tingi merupakan formula klasik pewarna sogan keraton.'),
(19,'Bentuk pola geometris yang membingkai ornamen Wahyu Tumurun adalah...','Belah ketupat (wajik) atau bidang kisi-kisi teratur simetris','Segitiga tajam berundak','Lingkaran acak konsentris','Garis zigzag patah-patah','A','Bidang kisi-kisi wajik simetris membingkai mahkota dan ornamen pendamping.'),
(19,'Ornamen sepasang burung merak berhadapan pada motif Wahyu Tumurun melambangkan...','Kesetiaan cinta, keindahan budi, dan keharmonisan pasangan hidup','Hama tanaman padi sawah','Pertanda datangnya angin badai','Tanda kemarahan ksatria','A','Merak berhadapan menyimbolkan keindahan cinta, kesetiaan, dan keharmonisan rumah tangga.'),
(19,'Ornamen sayap burung garuda (lar) perkasa melambangkan sifat kepemimpinan berupa...','Keberanian membela kebenaran, perlindungan agung, dan keteguhan iman','Keinginan menguasai angkasa raya','Simbol kesedihan duka cita','Rasa takut pada lawan','A','Lar garuda melambangkan perlindungan ilahi dan keteguhan menegakkan kebenaran.'),
(19,'Kain mori bermutu paling tinggi dengan anyaman benang rapat halus dinamakan...','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Parasut Tahan Angin','A','Mori Primissima adalah jenis katun nomor satu terbaik untuk membatik tulis halus.'),
(19,'Alat canting berbahan tembaga bergagang bambu berfungsi untuk...','Menorehkan cairan lilin malam panas secara presisi ke atas mori','Memotong kain mori yang kusut','Mencelup kain ke dalam pewarna soga','Menghaluskan serat kain mori','A','Canting tembaga adalah alat pena lilin utama dalam seni membatik tulis.'),
(19,'Tahap menutupi bidang gambar ornamen dengan lilin malam tebal dinamakan...','Nembok','Nglorod','Nyorek','Njaplak','A','Nembok adalah menutup bidang luas dengan malam agar tidak terkena warna celup.'),
(19,'Proses meluruhkan lapisan lilin malam dari kain menggunakan air mendidih dinamakan...','Nglorod','Medel','Nyungging','Ngasah','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(19,'Mengapa motif Wahyu Tumurun sangat digemari oleh para abdi dalem dan pejabat negara?','Karena memancarkan doa integritas moral, amanah kepemimpinan, dan wibawa terhormat','Karena harganya selalu paling murah','Karena dibuat menggunakan mesin fotokopi','Karena warnanya hanya satu macam','A','Wahyu Tumurun memancarkan aura kepemimpinan yang berwibawa, amanah, dan berintegritas.'),
(19,'Apakah fungsi isen sawut halus yang melengkung pada kelopak mahkota Wahyu Tumurun?','Memberikan tekstur kemilau tiga dimensi dan kesan keagungan permata mahkota','Menutup kain yang robek','Menambah berat timbangan kain','Menghapus coretan pola','A','Sawut berupa garis-garis lembut melengkung pemberi tekstur dan bayangan mahkota.'),
(19,'Sabun pembersih alami tradisional yang terbuat dari buah lerak berfungsi untuk...','Mencuci kain batik secara lembut tanpa merusak warna soga alami','Membuat warna kain cepat pudar','Menghilangkan aroma lilin malam','Mengeraskan serat kain mori','A','Lerak adalah pembersih alami ber-pH seimbang yang menjaga keawetan warna batik.'),
(19,'Batik Wahyu Tumurun termasuk dalam rumpun besar gaya...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Baduy Pesisir','A','Wahyu Tumurun merupakan mahakarya agung tradisi keraton Surakarta dan Yogyakarta.'),
(20,'Apakah arti kata ''Wirasat'' atau ''Firasat'' pada penamaan motif Batik ini?','Kepekaan mata batin, petunjuk nurani, dan wasiat nasihat luhur orang tua','Kekuatan memanah dari jarak jauh','Senjata pusaka berbilah tajam','Angin topan di lautan luas','A','Wirasat bermakna kepekaan batin, firasat nurani, dan wasiat petuah orang tua.'),
(20,'Pesan filosofis apakah yang menjadi inti ajaran moral Batik Wirasat?','Nasihat dan doa orang tua adalah bekal utama anak cucu mengarungi samudra kehidupan','Menumpuk kekayaan materi sebanyak mungkin','Menghiraukan nasihat para tetua keluarga','Membalas dendam kepada musuh lama','A','Wirasat menyimbolkan wasiat doa dan nasihat bijak orang tua penuntun anak cucu.'),
(20,'Ornamen khas apakah yang terdapat pada motif Wirasat sebagai lambang kemandirian mencari nafkah?','Ornamen Cakar Ayam','Ornamen Mahkota Kerajaan','Ornamen Kereta Perang','Ornamen Cakar Elang','A','Cakar ayam melambangkan kemandirian dan keuletan dalam mencari nafkah halal.'),
(20,'Ragam motif pusaka apakah yang sering dipadukan di dalam bidang wajik Wirasat?','Truntum, lidah api, cakar ayam, sidomukti, dan lung dedaunan obat','Ondel-ondel dan monas','Buket bunga tulip dan aster','Naga liong dan phoenix','A','Wirasat memadukan aneka motif pusaka sarat doa ke dalam kisi wajik.'),
(20,'Dari manakah lingkungan tradisi asal penciptaan Batik Wirasat?','Keraton Kasunanan Surakarta dan Kesultanan Yogyakarta','Pesisir Pantai Pekalongan','Pedalaman Hutan Kalimantan','Kawasan Pelabuhan Batavia','A','Wirasat merupakan motif pusaka klasik keraton Surakarta dan Yogyakarta.'),
(20,'Pada upacara pernikahan adat Jawa, kain Batik Wirasat lazim dikenakan oleh...','Orang tua kedua mempelai pengantin bersama motif Truntum','Para prajurit pengawal gerbang','Kusir kereta kuda pesta','Anak-anak pembawa bunga','A','Orang tua pengantin mengenakan Wirasat sebagai lambang doa restu dan wasiat nasihat.'),
(20,'Ornamen sulur dedaunan tanaman obat pada motif Wirasat melambangkan...','Perlindungan kesehatan, penolak bala marabahaya, dan umur panjang','Tanaman liar yang harus dibakar','Hama perusak tanaman padi','Rintangan di dalam hutan','A','Sulur tanaman obat melambangkan doa kesehatan lahir batin dan penolak bala.'),
(20,'Bentuk pola geometris apakah yang membingkai ragam ornamen pada Batik Wirasat?','Belah ketupat (wajik) yang tertata rapi simetris','Segitiga tajam berundak','Lingkaran konsentris acak','Garis lurus memanjang tanpa batas','A','Pola belah ketupat wajik simetris membingkai ornamen pusaka dalam harmoni yang teratur.'),
(20,'Warna klasik apakah yang mendominasi keagungan kain Batik Wirasat keraton?','Cokelat sogan matang, hitam pekat, dan dasar putih gading mori','Merah terang darah ayam pesisir','Biru toska muda dan kuning neon','Merah muda pastel pucat','A','Palet warna sogan klasik memancarkan aura keteduhan jiwa dan kemuliaan tradisi.'),
(20,'Bahan pewarna cokelat alami soga berasal dari campuran kulit pohon...','Soga jambal, kayu tegeran, dan kulit pohon tingi','Kulit buah durian','Akar rumput ilalang','Daun sirih kuning','A','Soga jambal, tegeran, dan tingi merupakan formula klasik pewarna sogan keraton.'),
(20,'Apakah arti penting ''kepekaan firasat'' dalam falsafah hidup masyarakat Jawa?','Kemampuan nurani membedakan yang haq dan yang batil serta waspada marabahaya','Kemampuan meramal masa depan orang lain','Menebak angka lotere perniagaan','Menghindari perjumpaan dengan tetangga','A','Firasat nurani menuntun manusia untuk senantiasa eling lan waspada dalam kebaikan.'),
(20,'Kain mori bermutu paling tinggi dengan anyaman benang rapat halus dinamakan...','Mori Primissima','Kain Blacu Kasar','Kain Goni Berbulu','Kain Parasut Tahan Angin','A','Mori Primissima adalah jenis katun nomor satu terbaik untuk membatik tulis halus.'),
(20,'Alat canting berbahan tembaga bergagang bambu berfungsi untuk...','Menorehkan cairan lilin malam panas secara presisi ke atas mori','Memotong kain mori yang kusut','Mencelup kain ke dalam pewarna soga','Menghaluskan serat kain mori','A','Canting tembaga adalah alat pena lilin utama dalam seni membatik tulis.'),
(20,'Tahap menutupi bidang gambar ornamen dengan lilin malam tebal dinamakan...','Nembok','Nglorod','Nyorek','Njaplak','A','Nembok adalah menutup bidang luas dengan malam agar tidak terkena warna celup.'),
(20,'Proses meluruhkan lapisan lilin malam dari kain menggunakan air mendidih dinamakan...','Nglorod','Medel','Nyungging','Ngasah','A','Nglorod adalah tahapan akhir perebusan untuk melarutkan seluruh lapisan lilin malam.'),
(20,'Dalam upacara ruwatan adat Jawa, kain Wirasat digunakan sebagai...','Kain sarana doa keselamatan dan tolak bala mara bahaya bagi keluarga','Kain pembersih lantai rumah','Alat penutup jendela gudang','Tali pengikat hewan ternak','A','Kain Wirasat menjadi sarana doa sakral tolak bala dan keselamatan keluarga.'),
(20,'Mengapa motif Wirasat disebut sebagai motif sarat pesan nasihat kehidupan?','Karena setiap ornamen di dalamnya memuat simbol kebijaksanaan dan tuntunan moral leluhur','Karena memuat tulisan huruf latin panjang','Karena harganya selalu paling mahal','Karena hanya boleh dibuat oleh raja','A','Wirasat memadukan simbol kemandirian, cinta kasih, dan perlindungan moral.'),
(20,'Apakah fungsi isen sawut halus yang melengkung pada ornamen Batik Wirasat?','Memberikan kesan kedalaman tekstur tiga dimensi dan kelenturan ornamen','Menutup kain yang robek','Menambah berat timbangan kain','Menghapus coretan pola','A','Sawut berupa garis-garis lembut melengkung pemberi tekstur dan bayangan.'),
(20,'Sabun pembersih alami tradisional yang terbuat dari buah lerak berfungsi untuk...','Mencuci kain batik secara lembut tanpa merusak warna soga alami','Membuat warna kain cepat pudar','Menghilangkan aroma lilin malam','Mengeraskan serat kain mori','A','Lerak adalah pembersih alami ber-pH seimbang yang menjaga keawetan warna batik.'),
(20,'Batik Wirasat termasuk dalam rumpun besar gaya...','Batik Keraton Klasik (Vorstenlanden)','Batik Pesisiran Bebas','Batik Saudagaran Luar','Batik Baduy Pesisir','A','Wirasat merupakan mahakarya agung tradisi keraton Surakarta dan Yogyakarta.'),
(20,'Bahan baku lilin malam batik diramu dari campuran bahan alami berupa...','Gondorukem, damar mata kucing, dan lilin lebah (malam tawon)','Semen putih dan minyak goreng','Tepung tapioka dan getah karet','Pewarna tekstil dan air cuka','A','Lilin malam diramu dari gondorukem, damar mata kucing, dan lilin lebah.')
)
INSERT INTO quiz_questions (module_id, question, option_a, option_b, option_c, option_d, correct_option, explanation)
SELECT m.id, v.question, v.a, v.b, v.c, v.d, v.correct, v.explanation
FROM v JOIN modules m ON m.order_no = v.mod;

COMMIT;
